import fs from 'node:fs';
const files={"README.md": "# 📒 Sketchbook 한글판\n\n3인칭 캐릭터로 섬을 탐험하고 자동차, 비행기, 헬리콥터를 타는 3D 물리 놀이터입니다. 원작은 swift502의 Sketchbook이며, 이 저장소는 원작의 저작자 표시와 기능을 유지한 한국어 포크입니다.\n\n## 🎮 즐기는 방법\n\n기본 자유 탐험에서 WASD로 이동하고 Shift로 달리며 Space로 점프합니다. F로 가까운 차량에 탑승합니다. 탑승하면 화면 왼쪽에 해당 차량의 조작 방법이 표시됩니다. 오른쪽 시나리오 메뉴에서 타원형·터널·8자 트랙 경주, 루프·초대형 경사로, 항공기 체험으로 전환할 수 있습니다.\n\n| 기능 | 설명 |\n|---|---|\n| 자동차 | 가속·제동·후진, 조향, 주차 브레이크, 시점 전환 |\n| 비행기 | 가속·감속, 승강타·보조익·방향타 조작 |\n| 헬리콥터 | 상승·하강, 피치·요·롤 조작 |\n| 세계 설정 | 시간 흐름, 태양 높이와 방향 |\n| 그래픽 설정 | 그림자, 계단 현상 완화, FPS 표시 |\n| 자유 카메라 | 세계를 자유롭게 둘러보기 |\n\n## 🇰🇷 한글화 범위\n\n환영 화면, 로딩, 캐릭터·차량 조작 도움말, 시나리오 이름과 설명, 세계·설정 패널을 번역했습니다. 원본 식별자와 3D 자산은 유지하며 Noto Sans KR을 적용했습니다. 3D 모델이나 텍스처에 직접 그려진 표시는 원본 그대로입니다.\n\n## 🛠️ 개발·배포\n\n```bash\nnpm ci\nNODE_OPTIONS=--openssl-legacy-provider npm run build\n```\n\n구형 webpack 4가 최신 Node.js의 OpenSSL과 충돌하므로 위 옵션이 필요합니다. 정적 index.html, build 디렉터리를 GitHub Pages로 배포합니다. 배포 작업은 `.github/workflows/pages.yml`에서 수행합니다.\n\n## ⚠️ 알려진 제한\n\n- 데스크톱 키보드·마우스와 WebGL 지원 브라우저를 권장합니다. 모바일용 게임 조작은 제공하지 않습니다.\n- 경주는 원작과 마찬가지로 랩 수와 순위 판정이 없습니다.\n- 원작자는 2023년 2월 개발 종료를 알렸으며 원본 저장소는 현재 보관 상태입니다. 이 포크는 최신 엔진으로 전면 교체한 버전이 아닙니다.\n- 의존성은 원작의 구형 버전을 사용합니다. 개발 서버를 인터넷에 공개하지 마세요.\n\n## 📚 원작·라이선스\n\n원작: swift502 / Sketchbook. Three.js와 cannon.js 기반. MIT 라이선스와 원본 저작권 고지를 유지합니다. 원문 README는 `README.en.md`에 보존했습니다.\n", "index.html": "<!DOCTYPE html>\n<html lang=\"ko\">\n\n<head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n\t<title>Sketchbook 한글판</title>\n</head>\n\n<body>\n\t<script src=\"build/sketchbook.min.js\"></script>\n\t<script>\n\t\tconst world = new Sketchbook.World('build/assets/world.glb');\n\t</script>\n</body>\n\n</html>", "src/css/main.css": "@import \"modules/base.css\";\n@import \"modules/githubCorner.css\";\n@import \"modules/leftPanel.css\";\n@import \"modules/dat.gui.css\";\n@import \"modules/loadingScreen.css\";\n@import \"modules/cubeLoader.css\";\n@import \"modules/welcomeScreen.css\";\n\nbody, .sb-font, .swal2-popup, .dg, .dg input {font-family: \"Noto Sans KR\", sans-serif !important;}\n.ctrl-desc {font-size: 14px;}\n", "src/ts/characters/Character.ts": "import * as THREE from 'three';\nimport * as CANNON from 'cannon';\nimport * as _ from 'lodash';\nimport * as Utils from '../core/FunctionLibrary';\n\nimport { KeyBinding } from '../core/KeyBinding';\nimport { VectorSpringSimulator } from '../physics/spring_simulation/VectorSpringSimulator';\nimport { RelativeSpringSimulator } from '../physics/spring_simulation/RelativeSpringSimulator';\nimport { Idle } from './character_states/Idle';\nimport { EnteringVehicle } from './character_states/vehicles/EnteringVehicle';\nimport { ExitingVehicle } from './character_states/vehicles/ExitingVehicle';\nimport { OpenVehicleDoor as OpenVehicleDoor } from './character_states/vehicles/OpenVehicleDoor';\nimport { Driving } from './character_states/vehicles/Driving';\nimport { ExitingAirplane } from './character_states/vehicles/ExitingAirplane';\nimport { ICharacterAI } from '../interfaces/ICharacterAI';\nimport { World } from '../world/World';\nimport { IControllable } from '../interfaces/IControllable';\nimport { ICharacterState } from '../interfaces/ICharacterState';\nimport { IWorldEntity } from '../interfaces/IWorldEntity';\nimport { VehicleSeat } from '../vehicles/VehicleSeat';\nimport { Vehicle } from '../vehicles/Vehicle';\nimport { CollisionGroups } from '../enums/CollisionGroups';\nimport { CapsuleCollider } from '../physics/colliders/CapsuleCollider';\nimport { VehicleEntryInstance } from './VehicleEntryInstance';\nimport { SeatType } from '../enums/SeatType';\nimport { GroundImpactData } from './GroundImpactData';\nimport { ClosestObjectFinder } from '../core/ClosestObjectFinder';\nimport { Object3D } from 'three';\nimport { EntityType } from '../enums/EntityType';\n\nexport class Character extends THREE.Object3D implements IWorldEntity\n{\n\tpublic updateOrder: number = 1;\n\tpublic entityType: EntityType = EntityType.Character;\n\n\tpublic height: number = 0;\n\tpublic tiltContainer: THREE.Group;\n\tpublic modelContainer: THREE.Group;\n\tpublic materials: THREE.Material[] = [];\n\tpublic mixer: THREE.AnimationMixer;\n\tpublic animations: any[];\n\n\t// Movement\n\tpublic acceleration: THREE.Vector3 = new THREE.Vector3();\n\tpublic velocity: THREE.Vector3 = new THREE.Vector3();\n\tpublic arcadeVelocityInfluence: THREE.Vector3 = new THREE.Vector3();\n\tpublic velocityTarget: THREE.Vector3 = new THREE.Vector3();\n\tpublic arcadeVelocityIsAdditive: boolean = false;\n\n\tpublic defaultVelocitySimulatorDamping: number = 0.8;\n\tpublic defaultVelocitySimulatorMass: number = 50;\n\tpublic velocitySimulator: VectorSpringSimulator;\n\tpublic moveSpeed: number = 4;\n\tpublic angularVelocity: number = 0;\n\tpublic orientation: THREE.Vector3 = new THREE.Vector3(0, 0, 1);\n\tpublic orientationTarget: THREE.Vector3 = new THREE.Vector3(0, 0, 1);\n\tpublic defaultRotationSimulatorDamping: number = 0.5;\n\tpublic defaultRotationSimulatorMass: number = 10;\n\tpublic rotationSimulator: RelativeSpringSimulator;\n\tpublic viewVector: THREE.Vector3;\n\tpublic actions: { [action: string]: KeyBinding };\n\tpublic characterCapsule: CapsuleCollider;\n\t\n\t// Ray casting\n\tpublic rayResult: CANNON.RaycastResult = new CANNON.RaycastResult();\n\tpublic rayHasHit: boolean = false;\n\tpublic rayCastLength: number = 0.57;\n\tpublic raySafeOffset: number = 0.03;\n\tpublic wantsToJump: boolean = false;\n\tpublic initJumpSpeed: number = -1;\n\tpublic groundImpactData: GroundImpactData = new GroundImpactData();\n\tpublic raycastBox: THREE.Mesh;\n\t\n\tpublic world: World;\n\tpublic charState: ICharacterState;\n\tpublic behaviour: ICharacterAI;\n\t\n\t// Vehicles\n\tpublic controlledObject: IControllable;\n\tpublic occupyingSeat: VehicleSeat = null;\n\tpublic vehicleEntryInstance: VehicleEntryInstance = null;\n\t\n\tprivate physicsEnabled: boolean = true;\n\n\tconstructor(gltf: any)\n\t{\n\t\tsuper();\n\n\t\tthis.readCharacterData(gltf);\n\t\tthis.setAnimations(gltf.animations);\n\n\t\t// The visuals group is centered for easy character tilting\n\t\tthis.tiltContainer = new THREE.Group();\n\t\tthis.add(this.tiltContainer);\n\n\t\t// Model container is used to reliably ground the character, as animation can alter the position of the model itself\n\t\tthis.modelContainer = new THREE.Group();\n\t\tthis.modelContainer.position.y = -0.57;\n\t\tthis.tiltContainer.add(this.modelContainer);\n\t\tthis.modelContainer.add(gltf.scene);\n\n\t\tthis.mixer = new THREE.AnimationMixer(gltf.scene);\n\n\t\tthis.velocitySimulator = new VectorSpringSimulator(60, this.defaultVelocitySimulatorMass, this.defaultVelocitySimulatorDamping);\n\t\tthis.rotationSimulator = new RelativeSpringSimulator(60, this.defaultRotationSimulatorMass, this.defaultRotationSimulatorDamping);\n\n\t\tthis.viewVector = new THREE.Vector3();\n\n\t\t// Actions\n\t\tthis.actions = {\n\t\t\t'up': new KeyBinding('KeyW'),\n\t\t\t'down': new KeyBinding('KeyS'),\n\t\t\t'left': new KeyBinding('KeyA'),\n\t\t\t'right': new KeyBinding('KeyD'),\n\t\t\t'run': new KeyBinding('ShiftLeft'),\n\t\t\t'jump': new KeyBinding('Space'),\n\t\t\t'use': new KeyBinding('KeyE'),\n\t\t\t'enter': new KeyBinding('KeyF'),\n\t\t\t'enter_passenger': new KeyBinding('KeyG'),\n\t\t\t'seat_switch': new KeyBinding('KeyX'),\n\t\t\t'primary': new KeyBinding('Mouse0'),\n\t\t\t'secondary': new KeyBinding('Mouse1'),\n\t\t};\n\n\t\t// Physics\n\t\t// Player Capsule\n\t\tthis.characterCapsule = new CapsuleCollider({\n\t\t\tmass: 1,\n\t\t\tposition: new CANNON.Vec3(),\n\t\t\theight: 0.5,\n\t\t\tradius: 0.25,\n\t\t\tsegments: 8,\n\t\t\tfriction: 0.0\n\t\t});\n\t\t// capsulePhysics.physical.collisionFilterMask = ~CollisionGroups.Trimesh;\n\t\tthis.characterCapsule.body.shapes.forEach((shape) => {\n\t\t\t// tslint:disable-next-line: no-bitwise\n\t\t\tshape.collisionFilterMask = ~CollisionGroups.TrimeshColliders;\n\t\t});\n\t\tthis.characterCapsule.body.allowSleep = false;\n\n\t\t// Move character to different collision group for raycasting\n\t\tthis.characterCapsule.body.collisionFilterGroup = 2;\n\n\t\t// Disable character rotation\n\t\tthis.characterCapsule.body.fixedRotation = true;\n\t\tthis.characterCapsule.body.updateMassProperties();\n\n\t\t// Ray cast debug\n\t\tconst boxGeo = new THREE.BoxGeometry(0.1, 0.1, 0.1);\n\t\tconst boxMat = new THREE.MeshLambertMaterial({\n\t\t\tcolor: 0xff0000\n\t\t});\n\t\tthis.raycastBox = new THREE.Mesh(boxGeo, boxMat);\n\t\tthis.raycastBox.visible = false;\n\n\t\t// Physics pre/post step callback bindings\n\t\tthis.characterCapsule.body.preStep = (body: CANNON.Body) => { this.physicsPreStep(body, this); };\n\t\tthis.characterCapsule.body.postStep = (body: CANNON.Body) => { this.physicsPostStep(body, this); };\n\n\t\t// States\n\t\tthis.setState(new Idle(this));\n\t}\n\n\tpublic setAnimations(animations: []): void\n\t{\n\t\tthis.animations = animations;\n\t}\n\n\tpublic setArcadeVelocityInfluence(x: number, y: number = x, z: number = x): void\n\t{\n\t\tthis.arcadeVelocityInfluence.set(x, y, z);\n\t}\n\n\tpublic setViewVector(vector: THREE.Vector3): void\n\t{\n\t\tthis.viewVector.copy(vector).normalize();\n\t}\n\n\t/**\n\t * Set state to the player. Pass state class (function) name.\n\t * @param {function} State \n\t */\n\tpublic setState(state: ICharacterState): void\n\t{\n\t\tthis.charState = state;\n\t\tthis.charState.onInputChange();\n\t}\n\n\tpublic setPosition(x: number, y: number, z: number): void\n\t{\n\t\tif (this.physicsEnabled)\n\t\t{\n\t\t\tthis.characterCapsule.body.previousPosition = new CANNON.Vec3(x, y, z);\n\t\t\tthis.characterCapsule.body.position = new CANNON.Vec3(x, y, z);\n\t\t\tthis.characterCapsule.body.interpolatedPosition = new CANNON.Vec3(x, y, z);\n\t\t}\n\t\telse\n\t\t{\n\t\t\tthis.position.x = x;\n\t\t\tthis.position.y = y;\n\t\t\tthis.position.z = z;\n\t\t}\n\t}\n\n\tpublic resetVelocity(): void\n\t{\n\t\tthis.velocity.x = 0;\n\t\tthis.velocity.y = 0;\n\t\tthis.velocity.z = 0;\n\n\t\tthis.characterCapsule.body.velocity.x = 0;\n\t\tthis.characterCapsule.body.velocity.y = 0;\n\t\tthis.characterCapsule.body.velocity.z = 0;\n\n\t\tthis.velocitySimulator.init();\n\t}\n\n\tpublic setArcadeVelocityTarget(velZ: number, velX: number = 0, velY: number = 0): void\n\t{\n\t\tthis.velocityTarget.z = velZ;\n\t\tthis.velocityTarget.x = velX;\n\t\tthis.velocityTarget.y = velY;\n\t}\n\n\tpublic setOrientation(vector: THREE.Vector3, instantly: boolean = false): void\n\t{\n\t\tlet lookVector = new THREE.Vector3().copy(vector).setY(0).normalize();\n\t\tthis.orientationTarget.copy(lookVector);\n\t\t\n\t\tif (instantly)\n\t\t{\n\t\t\tthis.orientation.copy(lookVector);\n\t\t}\n\t}\n\n\tpublic resetOrientation(): void\n\t{\n\t\tconst forward = Utils.getForward(this);\n\t\tthis.setOrientation(forward, true);\n\t}\n\n\tpublic setBehaviour(behaviour: ICharacterAI): void\n\t{\n\t\tbehaviour.character = this;\n\t\tthis.behaviour = behaviour;\n\t}\n\n\tpublic setPhysicsEnabled(value: boolean): void {\n\t\tthis.physicsEnabled = value;\n\n\t\tif (value === true)\n\t\t{\n\t\t\tthis.world.physicsWorld.addBody(this.characterCapsule.body);\n\t\t}\n\t\telse\n\t\t{\n\t\t\tthis.world.physicsWorld.remove(this.characterCapsule.body);\n\t\t}\n\t}\n\n\tpublic readCharacterData(gltf: any): void\n\t{\n\t\tgltf.scene.traverse((child) => {\n\n\t\t\tif (child.isMesh)\n\t\t\t{\n\t\t\t\tUtils.setupMeshProperties(child);\n\n\t\t\t\tif (child.material !== undefined)\n\t\t\t\t{\n\t\t\t\t\tthis.materials.push(child.material);\n\t\t\t\t}\n\t\t\t}\n\t\t});\n\t}\n\n\tpublic handleKeyboardEvent(event: KeyboardEvent, code: string, pressed: boolean): void\n\t{\n\t\tif (this.controlledObject !== undefined)\n\t\t{\n\t\t\tthis.controlledObject.handleKeyboardEvent(event, code, pressed);\n\t\t}\n\t\telse\n\t\t{\n\t\t\t// Free camera\n\t\t\tif (code === 'KeyC' && pressed === true && event.shiftKey === true)\n\t\t\t{\n\t\t\t\tthis.resetControls();\n\t\t\t\tthis.world.cameraOperator.characterCaller = this;\n\t\t\t\tthis.world.inputManager.setInputReceiver(this.world.cameraOperator);\n\t\t\t}\n\t\t\telse if (code === 'KeyR' && pressed === true && event.shiftKey === true)\n\t\t\t{\n\t\t\t\tthis.world.restartScenario();\n\t\t\t}\n\t\t\telse\n\t\t\t{\n\t\t\t\tfor (const action in this.actions) {\n\t\t\t\t\tif (this.actions.hasOwnProperty(action)) {\n\t\t\t\t\t\tconst binding = this.actions[action];\n\t\n\t\t\t\t\t\tif (_.includes(binding.eventCodes, code))\n\t\t\t\t\t\t{\n\t\t\t\t\t\t\tthis.triggerAction(action, pressed);\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic handleMouseButton(event: MouseEvent, code: string, pressed: boolean): void\n\t{\n\t\tif (this.controlledObject !== undefined)\n\t\t{\n\t\t\tthis.controlledObject.handleMouseButton(event, code, pressed);\n\t\t}\n\t\telse\n\t\t{\n\t\t\tfor (const action in this.actions) {\n\t\t\t\tif (this.actions.hasOwnProperty(action)) {\n\t\t\t\t\tconst binding = this.actions[action];\n\n\t\t\t\t\tif (_.includes(binding.eventCodes, code))\n\t\t\t\t\t{\n\t\t\t\t\t\tthis.triggerAction(action, pressed);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic handleMouseMove(event: MouseEvent, deltaX: number, deltaY: number): void\n\t{\n\t\tif (this.controlledObject !== undefined)\n\t\t{\n\t\t\tthis.controlledObject.handleMouseMove(event, deltaX, deltaY);\n\t\t}\n\t\telse\n\t\t{\n\t\t\tthis.world.cameraOperator.move(deltaX, deltaY);\n\t\t}\n\t}\n\t\n\tpublic handleMouseWheel(event: WheelEvent, value: number): void\n\t{\n\t\tif (this.controlledObject !== undefined)\n\t\t{\n\t\t\tthis.controlledObject.handleMouseWheel(event, value);\n\t\t}\n\t\telse\n\t\t{\n\t\t\tthis.world.scrollTheTimeScale(value);\n\t\t}\n\t}\n\n\tpublic triggerAction(actionName: string, value: boolean): void\n\t{\n\t\t// Get action and set it's parameters\n\t\tlet action = this.actions[actionName];\n\n\t\tif (action.isPressed !== value)\n\t\t{\n\t\t\t// Set value\n\t\t\taction.isPressed = value;\n\n\t\t\t// Reset the 'just' attributes\n\t\t\taction.justPressed = false;\n\t\t\taction.justReleased = false;\n\n\t\t\t// Set the 'just' attributes\n\t\t\tif (value) action.justPressed = true;\n\t\t\telse action.justReleased = true;\n\n\t\t\t// Tell player to handle states according to new input\n\t\t\tthis.charState.onInputChange();\n\n\t\t\t// Reset the 'just' attributes\n\t\t\taction.justPressed = false;\n\t\t\taction.justReleased = false;\n\t\t}\n\t}\n\n\tpublic takeControl(): void\n\t{\n\t\tif (this.world !== undefined)\n\t\t{\n\t\t\tthis.world.inputManager.setInputReceiver(this);\n\t\t}\n\t\telse\n\t\t{\n\t\t\tconsole.warn('Attempting to take control of a character that doesn\\'t belong to a world.');\n\t\t}\n\t}\n\n\tpublic resetControls(): void\n\t{\n\t\tfor (const action in this.actions) {\n\t\t\tif (this.actions.hasOwnProperty(action)) {\n\t\t\t\tthis.triggerAction(action, false);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic update(timeStep: number): void\n\t{\n\t\tthis.behaviour?.update(timeStep);\n\t\tthis.vehicleEntryInstance?.update(timeStep);\n\t\t// console.log(this.occupyingSeat);\n\t\tthis.charState?.update(timeStep);\n\n\t\t// this.visuals.position.copy(this.modelOffset);\n\t\tif (this.physicsEnabled) this.springMovement(timeStep);\n\t\tif (this.physicsEnabled) this.springRotation(timeStep);\n\t\tif (this.physicsEnabled) this.rotateModel();\n\t\tif (this.mixer !== undefined) this.mixer.update(timeStep);\n\n\t\t// Sync physics/graphics\n\t\tif (this.physicsEnabled)\n\t\t{\n\t\t\tthis.position.set(\n\t\t\t\tthis.characterCapsule.body.interpolatedPosition.x,\n\t\t\t\tthis.characterCapsule.body.interpolatedPosition.y,\n\t\t\t\tthis.characterCapsule.body.interpolatedPosition.z\n\t\t\t);\n\t\t}\n\t\telse {\n\t\t\tlet newPos = new THREE.Vector3();\n\t\t\tthis.getWorldPosition(newPos);\n\n\t\t\tthis.characterCapsule.body.position.copy(Utils.cannonVector(newPos));\n\t\t\tthis.characterCapsule.body.interpolatedPosition.copy(Utils.cannonVector(newPos));\n\t\t}\n\n\t\tthis.updateMatrixWorld();\n\t}\n\n\tpublic inputReceiverInit(): void\n\t{\n\t\tif (this.controlledObject !== undefined)\n\t\t{\n\t\t\tthis.controlledObject.inputReceiverInit();\n\t\t\treturn;\n\t\t}\n\n\t\tthis.world.cameraOperator.setRadius(1.6, true);\n\t\tthis.world.cameraOperator.followMode = false;\n\t\t// this.world.dirLight.target = this;\n\n\t\tthis.displayControls();\n\t}\n\n\tpublic displayControls(): void\n\t{\n\t\tthis.world.updateControls([\n\t\t\t{\n\t\t\t\tkeys: ['W', 'A', 'S', 'D'],\n\t\t\t\tdesc: '이동'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['Shift'],\n\t\t\t\tdesc: '달리기'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['Space'],\n\t\t\t\tdesc: '점프'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['F', 'or', 'G'],\n\t\t\t\tdesc: '차량 탑승'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['Shift', '+', 'R'],\n\t\t\t\tdesc: '다시 출발'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['Shift', '+', 'C'],\n\t\t\t\tdesc: '자유 카메라'\n\t\t\t},\n\t\t]);\n\t}\n\n\tpublic inputReceiverUpdate(timeStep: number): void\n\t{\n\t\tif (this.controlledObject !== undefined)\n\t\t{\n\t\t\tthis.controlledObject.inputReceiverUpdate(timeStep);\n\t\t}\n\t\telse\n\t\t{\n\t\t\t// Look in camera's direction\n\t\t\tthis.viewVector = new THREE.Vector3().subVectors(this.position, this.world.camera.position);\n\t\t\tthis.getWorldPosition(this.world.cameraOperator.target);\n\t\t}\n\t\t\n\t}\n\n\tpublic setAnimation(clipName: string, fadeIn: number): number\n\t{\n\t\tif (this.mixer !== undefined)\n\t\t{\n\t\t\t// gltf\n\t\t\tlet clip = THREE.AnimationClip.findByName( this.animations, clipName );\n\n\t\t\tlet action = this.mixer.clipAction(clip);\n\t\t\tif (action === null)\n\t\t\t{\n\t\t\t\tconsole.error(`Animation ${clipName} not found!`);\n\t\t\t\treturn 0;\n\t\t\t}\n\n\t\t\tthis.mixer.stopAllAction();\n\t\t\taction.fadeIn(fadeIn);\n\t\t\taction.play();\n\n\t\t\treturn action.getClip().duration;\n\t\t}\n\t}\n\n\tpublic springMovement(timeStep: number): void\n\t{\n\t\t// Simulator\n\t\tthis.velocitySimulator.target.copy(this.velocityTarget);\n\t\tthis.velocitySimulator.simulate(timeStep);\n\n\t\t// Update values\n\t\tthis.velocity.copy(this.velocitySimulator.position);\n\t\tthis.acceleration.copy(this.velocitySimulator.velocity);\n\t}\n\n\tpublic springRotation(timeStep: number): void\n\t{\n\t\t// Spring rotation\n\t\t// Figure out angle between current and target orientation\n\t\tlet angle = Utils.getSignedAngleBetweenVectors(this.orientation, this.orientationTarget);\n\n\t\t// Simulator\n\t\tthis.rotationSimulator.target = angle;\n\t\tthis.rotationSimulator.simulate(timeStep);\n\t\tlet rot = this.rotationSimulator.position;\n\n\t\t// Updating values\n\t\tthis.orientation.applyAxisAngle(new THREE.Vector3(0, 1, 0), rot);\n\t\tthis.angularVelocity = this.rotationSimulator.velocity;\n\t}\n\n\tpublic getLocalMovementDirection(): THREE.Vector3\n\t{\n\t\tconst positiveX = this.actions.right.isPressed ? -1 : 0;\n\t\tconst negativeX = this.actions.left.isPressed ? 1 : 0;\n\t\tconst positiveZ = this.actions.up.isPressed ? 1 : 0;\n\t\tconst negativeZ = this.actions.down.isPressed ? -1 : 0;\n\n\t\treturn new THREE.Vector3(positiveX + negativeX, 0, positiveZ + negativeZ).normalize();\n\t}\n\n\tpublic getCameraRelativeMovementVector(): THREE.Vector3\n\t{\n\t\tconst localDirection = this.getLocalMovementDirection();\n\t\tconst flatViewVector = new THREE.Vector3(this.viewVector.x, 0, this.viewVector.z).normalize();\n\n\t\treturn Utils.appplyVectorMatrixXZ(flatViewVector, localDirection);\n\t}\n\n\tpublic setCameraRelativeOrientationTarget(): void\n\t{\n\t\tif (this.vehicleEntryInstance === null)\n\t\t{\n\t\t\tlet moveVector = this.getCameraRelativeMovementVector();\n\t\n\t\t\tif (moveVector.x === 0 && moveVector.y === 0 && moveVector.z === 0)\n\t\t\t{\n\t\t\t\tthis.setOrientation(this.orientation);\n\t\t\t}\n\t\t\telse\n\t\t\t{\n\t\t\t\tthis.setOrientation(moveVector);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic rotateModel(): void\n\t{\n\t\tthis.lookAt(this.position.x + this.orientation.x, this.position.y + this.orientation.y, this.position.z + this.orientation.z);\n\t\tthis.tiltContainer.rotation.z = (-this.angularVelocity * 2.3 * this.velocity.length());\n\t\tthis.tiltContainer.position.setY((Math.cos(Math.abs(this.angularVelocity * 2.3 * this.velocity.length())) / 2) - 0.5);\n\t}\n\n\tpublic jump(initJumpSpeed: number = -1): void\n\t{\n\t\tthis.wantsToJump = true;\n\t\tthis.initJumpSpeed = initJumpSpeed;\n\t}\n\n\tpublic findVehicleToEnter(wantsToDrive: boolean): void\n\t{\n\t\t// reusable world position variable\n\t\tlet worldPos = new THREE.Vector3();\n\n\t\t// Find best vehicle\n\t\tlet vehicleFinder = new ClosestObjectFinder<Vehicle>(this.position, 10);\n\t\tthis.world.vehicles.forEach((vehicle) =>\n\t\t{\n\t\t\tvehicleFinder.consider(vehicle, vehicle.position);\n\t\t});\n\n\t\tif (vehicleFinder.closestObject !== undefined)\n\t\t{\n\t\t\tlet vehicle = vehicleFinder.closestObject;\n\t\t\tlet vehicleEntryInstance = new VehicleEntryInstance(this);\n\t\t\tvehicleEntryInstance.wantsToDrive = wantsToDrive;\n\n\t\t\t// Find best seat\n\t\t\tlet seatFinder = new ClosestObjectFinder<VehicleSeat>(this.position);\n\t\t\tfor (const seat of vehicle.seats)\n\t\t\t{\n\t\t\t\tif (wantsToDrive)\n\t\t\t\t{\n\t\t\t\t\t// Consider driver seats\n\t\t\t\t\tif (seat.type === SeatType.Driver)\n\t\t\t\t\t{\n\t\t\t\t\t\tseat.seatPointObject.getWorldPosition(worldPos);\n\t\t\t\t\t\tseatFinder.consider(seat, worldPos);\n\t\t\t\t\t}\n\t\t\t\t\t// Consider passenger seats connected to driver seats\n\t\t\t\t\telse if (seat.type === SeatType.Passenger)\n\t\t\t\t\t{\n\t\t\t\t\t\tfor (const connSeat of seat.connectedSeats)\n\t\t\t\t\t\t{\n\t\t\t\t\t\t\tif (connSeat.type === SeatType.Driver)\n\t\t\t\t\t\t\t{\n\t\t\t\t\t\t\t\tseat.seatPointObject.getWorldPosition(worldPos);\n\t\t\t\t\t\t\t\tseatFinder.consider(seat, worldPos);\n\t\t\t\t\t\t\t\tbreak;\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\telse\n\t\t\t\t{\n\t\t\t\t\t// Consider passenger seats\n\t\t\t\t\tif (seat.type === SeatType.Passenger)\n\t\t\t\t\t{\n\t\t\t\t\t\tseat.seatPointObject.getWorldPosition(worldPos);\n\t\t\t\t\t\tseatFinder.consider(seat, worldPos);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\n\t\t\tif (seatFinder.closestObject !== undefined)\n\t\t\t{\n\t\t\t\tlet targetSeat = seatFinder.closestObject;\n\t\t\t\tvehicleEntryInstance.targetSeat = targetSeat;\n\n\t\t\t\tlet entryPointFinder = new ClosestObjectFinder<Object3D>(this.position);\n\n\t\t\t\tfor (const point of targetSeat.entryPoints) {\n\t\t\t\t\tpoint.getWorldPosition(worldPos);\n\t\t\t\t\tentryPointFinder.consider(point, worldPos);\n\t\t\t\t}\n\n\t\t\t\tif (entryPointFinder.closestObject !== undefined)\n\t\t\t\t{\n\t\t\t\t\tvehicleEntryInstance.entryPoint = entryPointFinder.closestObject;\n\t\t\t\t\tthis.triggerAction('up', true);\n\t\t\t\t\tthis.vehicleEntryInstance = vehicleEntryInstance;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic enterVehicle(seat: VehicleSeat, entryPoint: THREE.Object3D): void\n\t{\n\t\tthis.resetControls();\n\n\t\tif (seat.door?.rotation < 0.5)\n\t\t{\n\t\t\tthis.setState(new OpenVehicleDoor(this, seat, entryPoint));\n\t\t}\n\t\telse\n\t\t{\n\t\t\tthis.setState(new EnteringVehicle(this, seat, entryPoint));\n\t\t}\n\t}\n\n\tpublic teleportToVehicle(vehicle: Vehicle, seat: VehicleSeat): void\n\t{\n\t\tthis.resetVelocity();\n\t\tthis.rotateModel();\n\t\tthis.setPhysicsEnabled(false);\n\t\t(vehicle as unknown as THREE.Object3D).attach(this);\n\n\t\tthis.setPosition(seat.seatPointObject.position.x, seat.seatPointObject.position.y + 0.6, seat.seatPointObject.position.z);\n\t\tthis.quaternion.copy(seat.seatPointObject.quaternion);\n\n\t\tthis.occupySeat(seat);\n\t\tthis.setState(new Driving(this, seat));\n\n\t\tthis.startControllingVehicle(vehicle, seat);\n\t}\n\n\tpublic startControllingVehicle(vehicle: IControllable, seat: VehicleSeat): void\n\t{\n\t\tif (this.controlledObject !== vehicle)\n\t\t{\n\t\t\tthis.transferControls(vehicle);\n\t\t\tthis.resetControls();\n\t\n\t\t\tthis.controlledObject = vehicle;\n\t\t\tthis.controlledObject.allowSleep(false);\n\t\t\tvehicle.inputReceiverInit();\n\t\n\t\t\tvehicle.controllingCharacter = this;\n\t\t}\n\t}\n\n\tpublic transferControls(entity: IControllable): void\n\t{\n\t\t// Currently running through all actions of this character and the vehicle,\n\t\t// comparing keycodes of actions and based on that triggering vehicle's actions\n\t\t// Maybe we should ask input manager what's the current state of the keyboard\n\t\t// and read those values... TODO\n\t\tfor (const action1 in this.actions) {\n\t\t\tif (this.actions.hasOwnProperty(action1)) {\n\t\t\t\tfor (const action2 in entity.actions) {\n\t\t\t\t\tif (entity.actions.hasOwnProperty(action2)) {\n\n\t\t\t\t\t\tlet a1 = this.actions[action1];\n\t\t\t\t\t\tlet a2 = entity.actions[action2];\n\n\t\t\t\t\t\ta1.eventCodes.forEach((code1) => {\n\t\t\t\t\t\t\ta2.eventCodes.forEach((code2) => {\n\t\t\t\t\t\t\t\tif (code1 === code2)\n\t\t\t\t\t\t\t\t{\n\t\t\t\t\t\t\t\t\tentity.triggerAction(action2, a1.isPressed);\n\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t});\n\t\t\t\t\t\t});\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic stopControllingVehicle(): void\n\t{\n\t\tif (this.controlledObject?.controllingCharacter === this)\n\t\t{\n\t\t\tthis.controlledObject.allowSleep(true);\n\t\t\tthis.controlledObject.controllingCharacter = undefined;\n\t\t\tthis.controlledObject.resetControls();\n\t\t\tthis.controlledObject = undefined;\n\t\t\tthis.inputReceiverInit();\n\t\t}\n\t}\n\n\tpublic exitVehicle(): void\n\t{\n\t\tif (this.occupyingSeat !== null)\n\t\t{\n\t\t\tif (this.occupyingSeat.vehicle.entityType === EntityType.Airplane)\n\t\t\t{\n\t\t\t\tthis.setState(new ExitingAirplane(this, this.occupyingSeat));\n\t\t\t}\n\t\t\telse\n\t\t\t{\n\t\t\t\tthis.setState(new ExitingVehicle(this, this.occupyingSeat));\n\t\t\t}\n\t\t\t\n\t\t\tthis.stopControllingVehicle();\n\t\t}\n\t}\n\n\tpublic occupySeat(seat: VehicleSeat): void\n\t{\n\t\tthis.occupyingSeat = seat;\n\t\tseat.occupiedBy = this;\n\t}\n\n\tpublic leaveSeat(): void\n\t{\n\t\tif (this.occupyingSeat !== null)\n\t\t{\n\t\t\tthis.occupyingSeat.occupiedBy = null;\n\t\t\tthis.occupyingSeat = null;\n\t\t}\n\t}\n\n\tpublic physicsPreStep(body: CANNON.Body, character: Character): void\n\t{\n\t\tcharacter.feetRaycast();\n\n\t\t// Raycast debug\n\t\tif (character.rayHasHit)\n\t\t{\n\t\t\tif (character.raycastBox.visible) {\n\t\t\t\tcharacter.raycastBox.position.x = character.rayResult.hitPointWorld.x;\n\t\t\t\tcharacter.raycastBox.position.y = character.rayResult.hitPointWorld.y;\n\t\t\t\tcharacter.raycastBox.position.z = character.rayResult.hitPointWorld.z;\n\t\t\t}\n\t\t}\n\t\telse\n\t\t{\n\t\t\tif (character.raycastBox.visible) {\n\t\t\t\tcharacter.raycastBox.position.set(body.position.x, body.position.y - character.rayCastLength - character.raySafeOffset, body.position.z);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic feetRaycast(): void\n\t{\n\t\t// Player ray casting\n\t\t// Create ray\n\t\tlet body = this.characterCapsule.body;\n\t\tconst start = new CANNON.Vec3(body.position.x, body.position.y, body.position.z);\n\t\tconst end = new CANNON.Vec3(body.position.x, body.position.y - this.rayCastLength - this.raySafeOffset, body.position.z);\n\t\t// Raycast options\n\t\tconst rayCastOptions = {\n\t\t\tcollisionFilterMask: CollisionGroups.Default,\n\t\t\tskipBackfaces: true      /* ignore back faces */\n\t\t};\n\t\t// Cast the ray\n\t\tthis.rayHasHit = this.world.physicsWorld.raycastClosest(start, end, rayCastOptions, this.rayResult);\n\t}\n\n\tpublic physicsPostStep(body: CANNON.Body, character: Character): void\n\t{\n\t\t// Get velocities\n\t\tlet simulatedVelocity = new THREE.Vector3(body.velocity.x, body.velocity.y, body.velocity.z);\n\n\t\t// Take local velocity\n\t\tlet arcadeVelocity = new THREE.Vector3().copy(character.velocity).multiplyScalar(character.moveSpeed);\n\t\t// Turn local into global\n\t\tarcadeVelocity = Utils.appplyVectorMatrixXZ(character.orientation, arcadeVelocity);\n\n\t\tlet newVelocity = new THREE.Vector3();\n\n\t\t// Additive velocity mode\n\t\tif (character.arcadeVelocityIsAdditive)\n\t\t{\n\t\t\tnewVelocity.copy(simulatedVelocity);\n\n\t\t\tlet globalVelocityTarget = Utils.appplyVectorMatrixXZ(character.orientation, character.velocityTarget);\n\t\t\tlet add = new THREE.Vector3().copy(arcadeVelocity).multiply(character.arcadeVelocityInfluence);\n\n\t\t\tif (Math.abs(simulatedVelocity.x) < Math.abs(globalVelocityTarget.x * character.moveSpeed) || Utils.haveDifferentSigns(simulatedVelocity.x, arcadeVelocity.x)) { newVelocity.x += add.x; }\n\t\t\tif (Math.abs(simulatedVelocity.y) < Math.abs(globalVelocityTarget.y * character.moveSpeed) || Utils.haveDifferentSigns(simulatedVelocity.y, arcadeVelocity.y)) { newVelocity.y += add.y; }\n\t\t\tif (Math.abs(simulatedVelocity.z) < Math.abs(globalVelocityTarget.z * character.moveSpeed) || Utils.haveDifferentSigns(simulatedVelocity.z, arcadeVelocity.z)) { newVelocity.z += add.z; }\n\t\t}\n\t\telse\n\t\t{\n\t\t\tnewVelocity = new THREE.Vector3(\n\t\t\t\tTHREE.MathUtils.lerp(simulatedVelocity.x, arcadeVelocity.x, character.arcadeVelocityInfluence.x),\n\t\t\t\tTHREE.MathUtils.lerp(simulatedVelocity.y, arcadeVelocity.y, character.arcadeVelocityInfluence.y),\n\t\t\t\tTHREE.MathUtils.lerp(simulatedVelocity.z, arcadeVelocity.z, character.arcadeVelocityInfluence.z),\n\t\t\t);\n\t\t}\n\n\t\t// If we're hitting the ground, stick to ground\n\t\tif (character.rayHasHit)\n\t\t{\n\t\t\t// Flatten velocity\n\t\t\tnewVelocity.y = 0;\n\n\t\t\t// Move on top of moving objects\n\t\t\tif (character.rayResult.body.mass > 0)\n\t\t\t{\n\t\t\t\tlet pointVelocity = new CANNON.Vec3();\n\t\t\t\tcharacter.rayResult.body.getVelocityAtWorldPoint(character.rayResult.hitPointWorld, pointVelocity);\n\t\t\t\tnewVelocity.add(Utils.threeVector(pointVelocity));\n\t\t\t}\n\n\t\t\t// Measure the normal vector offset from direct \"up\" vector\n\t\t\t// and transform it into a matrix\n\t\t\tlet up = new THREE.Vector3(0, 1, 0);\n\t\t\tlet normal = new THREE.Vector3(character.rayResult.hitNormalWorld.x, character.rayResult.hitNormalWorld.y, character.rayResult.hitNormalWorld.z);\n\t\t\tlet q = new THREE.Quaternion().setFromUnitVectors(up, normal);\n\t\t\tlet m = new THREE.Matrix4().makeRotationFromQuaternion(q);\n\n\t\t\t// Rotate the velocity vector\n\t\t\tnewVelocity.applyMatrix4(m);\n\n\t\t\t// Compensate for gravity\n\t\t\t// newVelocity.y -= body.world.physicsWorld.gravity.y / body.character.world.physicsFrameRate;\n\n\t\t\t// Apply velocity\n\t\t\tbody.velocity.x = newVelocity.x;\n\t\t\tbody.velocity.y = newVelocity.y;\n\t\t\tbody.velocity.z = newVelocity.z;\n\t\t\t// Ground character\n\t\t\tbody.position.y = character.rayResult.hitPointWorld.y + character.rayCastLength + (newVelocity.y / character.world.physicsFrameRate);\n\t\t}\n\t\telse\n\t\t{\n\t\t\t// If we're in air\n\t\t\tbody.velocity.x = newVelocity.x;\n\t\t\tbody.velocity.y = newVelocity.y;\n\t\t\tbody.velocity.z = newVelocity.z;\n\n\t\t\t// Save last in-air information\n\t\t\tcharacter.groundImpactData.velocity.x = body.velocity.x;\n\t\t\tcharacter.groundImpactData.velocity.y = body.velocity.y;\n\t\t\tcharacter.groundImpactData.velocity.z = body.velocity.z;\n\t\t}\n\n\t\t// Jumping\n\t\tif (character.wantsToJump)\n\t\t{\n\t\t\t// If initJumpSpeed is set\n\t\t\tif (character.initJumpSpeed > -1)\n\t\t\t{\n\t\t\t\t// Flatten velocity\n\t\t\t\tbody.velocity.y = 0;\n\t\t\t\tlet speed = Math.max(character.velocitySimulator.position.length() * 4, character.initJumpSpeed);\n\t\t\t\tbody.velocity = Utils.cannonVector(character.orientation.clone().multiplyScalar(speed));\n\t\t\t}\n\t\t\telse {\n\t\t\t\t// Moving objects compensation\n\t\t\t\tlet add = new CANNON.Vec3();\n\t\t\t\tcharacter.rayResult.body.getVelocityAtWorldPoint(character.rayResult.hitPointWorld, add);\n\t\t\t\tbody.velocity.vsub(add, body.velocity);\n\t\t\t}\n\n\t\t\t// Add positive vertical velocity \n\t\t\tbody.velocity.y += 4;\n\t\t\t// Move above ground by 2x safe offset value\n\t\t\tbody.position.y += character.raySafeOffset * 2;\n\t\t\t// Reset flag\n\t\t\tcharacter.wantsToJump = false;\n\t\t}\n\t}\n\n\tpublic addToWorld(world: World): void\n\t{\n\t\tif (_.includes(world.characters, this))\n\t\t{\n\t\t\tconsole.warn('Adding character to a world in which it already exists.');\n\t\t}\n\t\telse\n\t\t{\n\t\t\t// Set world\n\t\t\tthis.world = world;\n\n\t\t\t// Register character\n\t\t\tworld.characters.push(this);\n\n\t\t\t// Register physics\n\t\t\tworld.physicsWorld.addBody(this.characterCapsule.body);\n\n\t\t\t// Add to graphicsWorld\n\t\t\tworld.graphicsWorld.add(this);\n\t\t\tworld.graphicsWorld.add(this.raycastBox);\n\n\t\t\t// Shadow cascades\n\t\t\tthis.materials.forEach((mat) =>\n\t\t\t{\n\t\t\t\tworld.sky.csm.setupMaterial(mat);\n\t\t\t});\n\t\t}\n\t}\n\n\tpublic removeFromWorld(world: World): void\n\t{\n\t\tif (!_.includes(world.characters, this))\n\t\t{\n\t\t\tconsole.warn('Removing character from a world in which it isn\\'t present.');\n\t\t}\n\t\telse\n\t\t{\n\t\t\tif (world.inputManager.inputReceiver === this)\n\t\t\t{\n\t\t\t\tworld.inputManager.inputReceiver = undefined;\n\t\t\t}\n\n\t\t\tthis.world = undefined;\n\n\t\t\t// Remove from characters\n\t\t\t_.pull(world.characters, this);\n\n\t\t\t// Remove physics\n\t\t\tworld.physicsWorld.remove(this.characterCapsule.body);\n\n\t\t\t// Remove visuals\n\t\t\tworld.graphicsWorld.remove(this);\n\t\t\tworld.graphicsWorld.remove(this.raycastBox);\n\t\t}\n\t}\n}", "src/ts/characters/character_states/vehicles/Sitting.ts": "import\n{\n\tCharacterStateBase,\n} from '../_stateLibrary';\nimport { Character } from '../../Character';\nimport { VehicleSeat } from 'src/ts/vehicles/VehicleSeat';\nimport { CloseVehicleDoorInside } from './CloseVehicleDoorInside';\nimport { SeatType } from '../../../enums/SeatType';\nimport { SwitchingSeats } from './SwitchingSeats';\n\nexport class Sitting extends CharacterStateBase\n{\n\tprivate seat: VehicleSeat;\n\n\tconstructor(character: Character, seat: VehicleSeat)\n\t{\n\t\tsuper(character);\n\n\t\tthis.seat = seat;\n\t\tthis.canFindVehiclesToEnter = false;\n\n\t\tthis.character.world.updateControls([\n\t\t\t{\n\t\t\t\tkeys: ['X'],\n\t\t\t\tdesc: '좌석 변경',\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['F'],\n\t\t\t\tdesc: '자리에서 나오기',\n\t\t\t}\n\t\t]);\n\t\t\n\t\tthis.playAnimation('sitting', 0.1);\n\t}\n\n\tpublic update(timeStep: number): void\n\t{\n\t\tsuper.update(timeStep);\n\n\t\tif (!this.seat.door?.achievingTargetRotation && this.seat.door?.rotation > 0 && this.noDirection())\n\t\t{\n\t\t\tthis.character.setState(new CloseVehicleDoorInside(this.character, this.seat));\n\t\t}\n\t\telse if (this.character.vehicleEntryInstance !== null)\n\t\t{\n\t\t\tif (this.character.vehicleEntryInstance.wantsToDrive)\n\t\t\t{\n\t\t\t\tfor (const possibleDriverSeat of this.seat.connectedSeats)\n\t\t\t\t{\n\t\t\t\t\tif (possibleDriverSeat.type === SeatType.Driver)\n\t\t\t\t\t{\n\t\t\t\t\t\tif (this.seat.door?.rotation > 0) this.seat.door.physicsEnabled = true;\n\t\t\t\t\t\tthis.character.setState(new SwitchingSeats(this.character, this.seat, possibleDriverSeat));\n\t\t\t\t\t\tbreak;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\telse\n\t\t\t{\n\t\t\t\tthis.character.vehicleEntryInstance = null;\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic onInputChange(): void\n\t{\n\t\tif (this.character.actions.seat_switch.justPressed && this.seat.connectedSeats.length > 0)\n\t\t{\n\t\t\tthis.character.setState(new SwitchingSeats(this.character, this.seat, this.seat.connectedSeats[0]));\n\t\t}\n\n\t\tif (this.character.actions.enter.justPressed)\n\t\t{\n\t\t\tthis.character.exitVehicle();\n\t\t\tthis.character.displayControls();\n\t\t}\n\t}\n}", "src/ts/core/CameraOperator.ts": "import * as THREE from 'three';\nimport * as Utils from './FunctionLibrary';\nimport { World } from '../world/World';\nimport { IInputReceiver } from '../interfaces/IInputReceiver';\nimport { KeyBinding } from './KeyBinding';\nimport { Character } from '../characters/Character';\nimport _ = require('lodash');\nimport { IUpdatable } from '../interfaces/IUpdatable';\n\nexport class CameraOperator implements IInputReceiver, IUpdatable\n{\n\tpublic updateOrder: number = 4;\n\n\tpublic world: World;\n\tpublic camera: THREE.Camera;\n\tpublic target: THREE.Vector3;\n\tpublic sensitivity: THREE.Vector2;\n\tpublic radius: number = 1;\n\tpublic theta: number;\n\tpublic phi: number;\n\tpublic onMouseDownPosition: THREE.Vector2;\n\tpublic onMouseDownTheta: any;\n\tpublic onMouseDownPhi: any;\n\tpublic targetRadius: number = 1;\n\n\tpublic movementSpeed: number;\n\tpublic actions: { [action: string]: KeyBinding };\n\n\tpublic upVelocity: number = 0;\n\tpublic forwardVelocity: number = 0;\n\tpublic rightVelocity: number = 0;\n\n\tpublic followMode: boolean = false;\n\n\tpublic characterCaller: Character;\n\n\tconstructor(world: World, camera: THREE.Camera, sensitivityX: number = 1, sensitivityY: number = sensitivityX * 0.8)\n\t{\n\t\tthis.world = world;\n\t\tthis.camera = camera;\n\t\tthis.target = new THREE.Vector3();\n\t\tthis.sensitivity = new THREE.Vector2(sensitivityX, sensitivityY);\n\n\t\tthis.movementSpeed = 0.06;\n\t\tthis.radius = 3;\n\t\tthis.theta = 0;\n\t\tthis.phi = 0;\n\n\t\tthis.onMouseDownPosition = new THREE.Vector2();\n\t\tthis.onMouseDownTheta = this.theta;\n\t\tthis.onMouseDownPhi = this.phi;\n\n\t\tthis.actions = {\n\t\t\t'forward': new KeyBinding('KeyW'),\n\t\t\t'back': new KeyBinding('KeyS'),\n\t\t\t'left': new KeyBinding('KeyA'),\n\t\t\t'right': new KeyBinding('KeyD'),\n\t\t\t'up': new KeyBinding('KeyE'),\n\t\t\t'down': new KeyBinding('KeyQ'),\n\t\t\t'fast': new KeyBinding('ShiftLeft'),\n\t\t};\n\n\t\tworld.registerUpdatable(this);\n\t}\n\n\tpublic setSensitivity(sensitivityX: number, sensitivityY: number = sensitivityX): void\n\t{\n\t\tthis.sensitivity = new THREE.Vector2(sensitivityX, sensitivityY);\n\t}\n\n\tpublic setRadius(value: number, instantly: boolean = false): void\n\t{\n\t\tthis.targetRadius = Math.max(0.001, value);\n\t\tif (instantly === true)\n\t\t{\n\t\t\tthis.radius = value;\n\t\t}\n\t}\n\n\tpublic move(deltaX: number, deltaY: number): void\n\t{\n\t\tthis.theta -= deltaX * (this.sensitivity.x / 2);\n\t\tthis.theta %= 360;\n\t\tthis.phi += deltaY * (this.sensitivity.y / 2);\n\t\tthis.phi = Math.min(85, Math.max(-85, this.phi));\n\t}\n\n\tpublic update(timeScale: number): void\n\t{\n\t\tif (this.followMode === true)\n\t\t{\n\t\t\tthis.camera.position.y = THREE.MathUtils.clamp(this.camera.position.y, this.target.y, Number.POSITIVE_INFINITY);\n\t\t\tthis.camera.lookAt(this.target);\n\t\t\tlet newPos = this.target.clone().add(new THREE.Vector3().subVectors(this.camera.position, this.target).normalize().multiplyScalar(this.targetRadius));\n\t\t\tthis.camera.position.x = newPos.x;\n\t\t\tthis.camera.position.y = newPos.y;\n\t\t\tthis.camera.position.z = newPos.z;\n\t\t}\n\t\telse \n\t\t{\n\t\t\tthis.radius = THREE.MathUtils.lerp(this.radius, this.targetRadius, 0.1);\n\t\n\t\t\tthis.camera.position.x = this.target.x + this.radius * Math.sin(this.theta * Math.PI / 180) * Math.cos(this.phi * Math.PI / 180);\n\t\t\tthis.camera.position.y = this.target.y + this.radius * Math.sin(this.phi * Math.PI / 180);\n\t\t\tthis.camera.position.z = this.target.z + this.radius * Math.cos(this.theta * Math.PI / 180) * Math.cos(this.phi * Math.PI / 180);\n\t\t\tthis.camera.updateMatrix();\n\t\t\tthis.camera.lookAt(this.target);\n\t\t}\n\t}\n\n\tpublic handleKeyboardEvent(event: KeyboardEvent, code: string, pressed: boolean): void\n\t{\n\t\t// Free camera\n\t\tif (code === 'KeyC' && pressed === true && event.shiftKey === true)\n\t\t{\n\t\t\tif (this.characterCaller !== undefined)\n\t\t\t{\n\t\t\t\tthis.world.inputManager.setInputReceiver(this.characterCaller);\n\t\t\t\tthis.characterCaller = undefined;\n\t\t\t}\n\t\t}\n\t\telse\n\t\t{\n\t\t\tfor (const action in this.actions) {\n\t\t\t\tif (this.actions.hasOwnProperty(action)) {\n\t\t\t\t\tconst binding = this.actions[action];\n\t\n\t\t\t\t\tif (_.includes(binding.eventCodes, code))\n\t\t\t\t\t{\n\t\t\t\t\t\tbinding.isPressed = pressed;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic handleMouseWheel(event: WheelEvent, value: number): void\n\t{\n\t\tthis.world.scrollTheTimeScale(value);\n\t}\n\n\tpublic handleMouseButton(event: MouseEvent, code: string, pressed: boolean): void\n\t{\n\t\tfor (const action in this.actions) {\n\t\t\tif (this.actions.hasOwnProperty(action)) {\n\t\t\t\tconst binding = this.actions[action];\n\n\t\t\t\tif (_.includes(binding.eventCodes, code))\n\t\t\t\t{\n\t\t\t\t\tbinding.isPressed = pressed;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic handleMouseMove(event: MouseEvent, deltaX: number, deltaY: number): void\n\t{\n\t\tthis.move(deltaX, deltaY);\n\t}\n\n\tpublic inputReceiverInit(): void\n\t{\n\t\tthis.target.copy(this.camera.position);\n\t\tthis.setRadius(0, true);\n\t\t// this.world.dirLight.target = this.world.camera;\n\n\t\tthis.world.updateControls([\n\t\t\t{\n\t\t\t\tkeys: ['W', 'S', 'A', 'D'],\n\t\t\t\tdesc: '이동'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['E', 'Q'],\n\t\t\t\tdesc: '위 / 아래로 이동'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['Shift'],\n\t\t\t\tdesc: '빠르게 이동'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['Shift', '+', 'C'],\n\t\t\t\tdesc: '자유 카메라 종료'\n\t\t\t},\n\t\t]);\n\t}\n\n\tpublic inputReceiverUpdate(timeStep: number): void\n\t{\n\t\t// Set fly speed\n\t\tlet speed = this.movementSpeed * (this.actions.fast.isPressed ? timeStep * 600 : timeStep * 60);\n\n\t\tconst up = Utils.getUp(this.camera);\n\t\tconst right = Utils.getRight(this.camera);\n\t\tconst forward = Utils.getBack(this.camera);\n\n\t\tthis.upVelocity = THREE.MathUtils.lerp(this.upVelocity, +this.actions.up.isPressed - +this.actions.down.isPressed, 0.3);\n\t\tthis.forwardVelocity = THREE.MathUtils.lerp(this.forwardVelocity, +this.actions.forward.isPressed - +this.actions.back.isPressed, 0.3);\n\t\tthis.rightVelocity = THREE.MathUtils.lerp(this.rightVelocity, +this.actions.right.isPressed - +this.actions.left.isPressed, 0.3);\n\n\t\tthis.target.add(up.multiplyScalar(speed * this.upVelocity));\n\t\tthis.target.add(forward.multiplyScalar(speed * this.forwardVelocity));\n\t\tthis.target.add(right.multiplyScalar(speed * this.rightVelocity));\n\t}\n}", "src/ts/vehicles/Airplane.ts": "import * as THREE from 'three';\nimport * as CANNON from 'cannon';\n\nimport { Vehicle } from './Vehicle';\nimport { IControllable } from '../interfaces/IControllable';\nimport { IWorldEntity } from '../interfaces/IWorldEntity';\nimport { KeyBinding } from '../core/KeyBinding';\nimport { SpringSimulator } from '../physics/spring_simulation/SpringSimulator';\nimport * as Utils from '../core/FunctionLibrary';\nimport { EntityType } from '../enums/EntityType';\n\nexport class Airplane extends Vehicle implements IControllable, IWorldEntity\n{\n\tpublic entityType: EntityType = EntityType.Airplane;\n\tpublic rotor: THREE.Object3D;\n\tpublic leftAileron: THREE.Object3D;\n\tpublic rightAileron: THREE.Object3D;\n\tpublic elevators: THREE.Object3D[] = [];\n\tpublic rudder: THREE.Object3D;\n\n\tprivate steeringSimulator: SpringSimulator; \n\tprivate aileronSimulator: SpringSimulator;\n\tprivate elevatorSimulator: SpringSimulator;\n\tprivate rudderSimulator: SpringSimulator;\n\n\tprivate enginePower: number = 0;\n\tprivate lastDrag: number = 0;\n\n\tconstructor(gltf: any)\n\t{\n\t\tsuper(gltf, {\n\t\t\tradius: 0.12,\n\t\t\tsuspensionStiffness: 150,\n\t\t\tsuspensionRestLength: 0.25,\n\t\t\tdampingRelaxation: 5,\n\t\t\tdampingCompression: 5,\n\t\t\tdirectionLocal: new CANNON.Vec3(0, -1, 0),\n\t\t\taxleLocal: new CANNON.Vec3(-1, 0, 0),\n\t\t\tchassisConnectionPointLocal: new CANNON.Vec3(),\n\t\t});\n\n\t\tthis.readAirplaneData(gltf);\n\n\t\tthis.collision.preStep = (body: CANNON.Body) => { this.physicsPreStep(body, this); };\n\n\t\tthis.actions = {\n\t\t\t'throttle': new KeyBinding('ShiftLeft'),\n\t\t\t'brake': new KeyBinding('Space'),\n\t\t\t'wheelBrake': new KeyBinding('KeyB'),\n\t\t\t'pitchUp': new KeyBinding('KeyS'),\n\t\t\t'pitchDown': new KeyBinding('KeyW'),\n\t\t\t'yawLeft': new KeyBinding('KeyQ'),\n\t\t\t'yawRight': new KeyBinding('KeyE'),\n\t\t\t'rollLeft': new KeyBinding('KeyA'),\n\t\t\t'rollRight': new KeyBinding('KeyD'),\n\t\t\t'exitVehicle': new KeyBinding('KeyF'),\n\t\t\t'seat_switch': new KeyBinding('KeyX'),\n\t\t\t'view': new KeyBinding('KeyV'),\n\t\t};\n\n\t\tthis.steeringSimulator = new SpringSimulator(60, 10, 0.6); \n\t\tthis.aileronSimulator = new SpringSimulator(60, 5, 0.6);\n\t\tthis.elevatorSimulator = new SpringSimulator(60, 7, 0.6);\n\t\tthis.rudderSimulator = new SpringSimulator(60, 10, 0.6);\n\t}\n\n\tpublic noDirectionPressed(): boolean\n\t{\n\t\tlet result = \n\t\t!this.actions.throttle.isPressed &&\n\t\t!this.actions.brake.isPressed &&\n\t\t!this.actions.yawLeft.isPressed &&\n\t\t!this.actions.yawRight.isPressed &&\n\t\t!this.actions.rollLeft.isPressed &&\n\t\t!this.actions.rollRight.isPressed;\n\n\t\treturn result;\n\t}\n\n\tpublic update(timeStep: number): void\n\t{\n\t\tsuper.update(timeStep);\n\t\t\n\t\t// Rotors visuals\n\t\tif (this.controllingCharacter !== undefined)\n\t\t{\n\t\t\tif (this.enginePower < 1) this.enginePower += timeStep * 0.4;\n\t\t\tif (this.enginePower > 1) this.enginePower = 1;\n\t\t}\n\t\telse\n\t\t{\n\t\t\tif (this.enginePower > 0) this.enginePower -= timeStep * 0.12;\n\t\t\tif (this.enginePower < 0) this.enginePower = 0;\n\t\t}\n\t\tthis.rotor.rotateX(this.enginePower * timeStep * 60);\n\n\t\t// Steering\n\t\tif (this.rayCastVehicle.numWheelsOnGround > 0)\n\t\t{\n\t\t\tif ((this.actions.yawLeft.isPressed || this.actions.rollLeft.isPressed)\n\t\t\t\t&& !this.actions.yawRight.isPressed && !this.actions.rollRight.isPressed)\n\t\t\t{\n\t\t\t\tthis.steeringSimulator.target = 0.8;\n\t\t\t}\n\t\t\telse if ((this.actions.yawRight.isPressed || this.actions.rollRight.isPressed)\n\t\t\t\t&& !this.actions.yawLeft.isPressed && !this.actions.rollLeft.isPressed)\n\t\t\t{\n\t\t\t\tthis.steeringSimulator.target = -0.8;\n\t\t\t}\n\t\t\telse\n\t\t\t{\n\t\t\t\tthis.steeringSimulator.target = 0;\n\t\t\t}\n\t\t}\n\t\telse\n\t\t{\n\t\t\tthis.steeringSimulator.target = 0;\n\t\t}\n\t\tthis.steeringSimulator.simulate(timeStep);\n\t\tthis.setSteeringValue(this.steeringSimulator.position);\n\n\t\tconst partsRotationAmount = 0.7;\n\n\t\t// Ailerons\n\t\tif (this.actions.rollLeft.isPressed && !this.actions.rollRight.isPressed)\n\t\t{\n\t\t\tthis.aileronSimulator.target = partsRotationAmount;\n\t\t}\n\t\telse if (!this.actions.rollLeft.isPressed && this.actions.rollRight.isPressed)\n\t\t{\n\t\t\tthis.aileronSimulator.target = -partsRotationAmount;\n\t\t}\n\t\telse \n\t\t{\n\t\t\tthis.aileronSimulator.target = 0;\n\t\t}\n\n\t\t// Elevators\n\t\tif (this.actions.pitchUp.isPressed && !this.actions.pitchDown.isPressed)\n\t\t{\n\t\t\tthis.elevatorSimulator.target = partsRotationAmount;\n\t\t}\n\t\telse if (!this.actions.pitchUp.isPressed && this.actions.pitchDown.isPressed)\n\t\t{\n\t\t\tthis.elevatorSimulator.target = -partsRotationAmount;\n\t\t}\n\t\telse\n\t\t{\n\t\t\tthis.elevatorSimulator.target = 0;\n\t\t}\n\n\t\t// Rudder\n\t\tif (this.actions.yawLeft.isPressed && !this.actions.yawRight.isPressed)\n\t\t{\n\t\t\tthis.rudderSimulator.target = partsRotationAmount;\n\t\t}\n\t\telse if (!this.actions.yawLeft.isPressed && this.actions.yawRight.isPressed)\n\t\t{\n\t\t\tthis.rudderSimulator.target = -partsRotationAmount;\n\t\t}\n\t\telse \n\t\t{\n\t\t\tthis.rudderSimulator.target = 0;\n\t\t}\n\n\t\t// Run rotation simulators\n\t\tthis.aileronSimulator.simulate(timeStep);\n\t\tthis.elevatorSimulator.simulate(timeStep);\n\t\tthis.rudderSimulator.simulate(timeStep);\n\n\t\t// Rotate parts\n\t\tthis.leftAileron.rotation.y = this.aileronSimulator.position;\n\t\tthis.rightAileron.rotation.y = -this.aileronSimulator.position;\n\t\tthis.elevators.forEach((elevator) =>\n\t\t{\n\t\t\televator.rotation.y = this.elevatorSimulator.position;\n\t\t});\n\t\tthis.rudder.rotation.y = this.rudderSimulator.position;\n\t}\n\n\tpublic physicsPreStep(body: CANNON.Body, plane: Airplane): void\n\t{\n\t\tlet quat = Utils.threeQuat(body.quaternion);\n\t\tlet right = new THREE.Vector3(1, 0, 0).applyQuaternion(quat);\n\t\tlet up = new THREE.Vector3(0, 1, 0).applyQuaternion(quat);\n\t\tlet forward = new THREE.Vector3(0, 0, 1).applyQuaternion(quat);\n\t\t\n\t\tconst velocity = new CANNON.Vec3().copy(this.collision.velocity);\n\t\tlet velLength1 = body.velocity.length();\n\t\tconst currentSpeed = velocity.dot(Utils.cannonVector(forward));\n\n\t\t// Rotation controls influence\n\t\tlet flightModeInfluence = currentSpeed / 10;\n\t\tflightModeInfluence = THREE.MathUtils.clamp(flightModeInfluence, 0, 1);\n\n\t\tlet lowerMassInfluence = currentSpeed / 10;\n\t\tlowerMassInfluence = THREE.MathUtils.clamp(lowerMassInfluence, 0, 1);\n\t\tthis.collision.mass = 50 * (1 - (lowerMassInfluence * 0.6));\n\n\t\t// Rotation stabilization\n\t\tlet lookVelocity = body.velocity.clone();\n\t\tlookVelocity.normalize();\n\t\tlet rotStabVelocity = new THREE.Quaternion().setFromUnitVectors(forward, Utils.threeVector(lookVelocity));\n\t\trotStabVelocity.x *= 0.3;\n\t\trotStabVelocity.y *= 0.3;\n\t\trotStabVelocity.z *= 0.3;\n\t\trotStabVelocity.w *= 0.3;\n\t\tlet rotStabEuler = new THREE.Euler().setFromQuaternion(rotStabVelocity);\n\n\t\tlet rotStabInfluence = THREE.MathUtils.clamp(velLength1 - 1, 0, 0.1);  // Only with speed greater than 1 UPS\n\t\trotStabInfluence *= (this.rayCastVehicle.numWheelsOnGround > 0 && currentSpeed < 0 ? 0 : 1);    // Reverse fix\n\t\tlet loopFix = (this.actions.throttle.isPressed && currentSpeed > 0 ? 0 : 1);\n\t\t\n\t\tbody.angularVelocity.x += rotStabEuler.x * rotStabInfluence * loopFix;\n\t\tbody.angularVelocity.y += rotStabEuler.y * rotStabInfluence;\n\t\tbody.angularVelocity.z += rotStabEuler.z * rotStabInfluence * loopFix;\n\n\t\t// Pitch\n\t\tif (plane.actions.pitchUp.isPressed)\n\t\t{\n\t\t\tbody.angularVelocity.x -= right.x * 0.04 * flightModeInfluence * this.enginePower;\n\t\t\tbody.angularVelocity.y -= right.y * 0.04 * flightModeInfluence * this.enginePower;\n\t\t\tbody.angularVelocity.z -= right.z * 0.04 * flightModeInfluence * this.enginePower;\n\t\t}\n\t\tif (plane.actions.pitchDown.isPressed)\n\t\t{\n\t\t\tbody.angularVelocity.x += right.x * 0.04 * flightModeInfluence * this.enginePower;\n\t\t\tbody.angularVelocity.y += right.y * 0.04 * flightModeInfluence * this.enginePower;\n\t\t\tbody.angularVelocity.z += right.z * 0.04 * flightModeInfluence * this.enginePower;\n\t\t}\n\n\t\t// Yaw\n\t\tif (plane.actions.yawLeft.isPressed)\n\t\t{\n\t\t\tbody.angularVelocity.x += up.x * 0.02 * flightModeInfluence * this.enginePower;\n\t\t\tbody.angularVelocity.y += up.y * 0.02 * flightModeInfluence * this.enginePower;\n\t\t\tbody.angularVelocity.z += up.z * 0.02 * flightModeInfluence * this.enginePower;\n\t\t}\n\t\tif (plane.actions.yawRight.isPressed)\n\t\t{\n\t\t\tbody.angularVelocity.x -= up.x * 0.02 * flightModeInfluence * this.enginePower;\n\t\t\tbody.angularVelocity.y -= up.y * 0.02 * flightModeInfluence * this.enginePower;\n\t\t\tbody.angularVelocity.z -= up.z * 0.02 * flightModeInfluence * this.enginePower;\n\t\t}\n\n\t\t// Roll\n\t\tif (plane.actions.rollLeft.isPressed)\n\t\t{\n\t\t\tbody.angularVelocity.x -= forward.x * 0.055 * flightModeInfluence * this.enginePower;\n\t\t\tbody.angularVelocity.y -= forward.y * 0.055 * flightModeInfluence * this.enginePower;\n\t\t\tbody.angularVelocity.z -= forward.z * 0.055 * flightModeInfluence * this.enginePower;\n\t\t}\n\t\tif (plane.actions.rollRight.isPressed)\n\t\t{\n\t\t\tbody.angularVelocity.x += forward.x * 0.055 * flightModeInfluence * this.enginePower;\n\t\t\tbody.angularVelocity.y += forward.y * 0.055 * flightModeInfluence * this.enginePower;\n\t\t\tbody.angularVelocity.z += forward.z * 0.055 * flightModeInfluence * this.enginePower;\n\t\t}\n\n\t\t// Thrust\n\t\tlet speedModifier = 0.02;\n\t\tif (plane.actions.throttle.isPressed && !plane.actions.brake.isPressed)\n\t\t{\n\t\t\tspeedModifier = 0.06;\n\t\t}\n\t\telse if (!plane.actions.throttle.isPressed && plane.actions.brake.isPressed)\n\t\t{\n\t\t\tspeedModifier = -0.05;\n\t\t}\n\t\telse if (this.rayCastVehicle.numWheelsOnGround > 0)\n\t\t{\n\t\t\tspeedModifier = 0;\n\t\t}\n\n\t\tbody.velocity.x += (velLength1 * this.lastDrag + speedModifier) * forward.x * this.enginePower;\n\t\tbody.velocity.y += (velLength1 * this.lastDrag + speedModifier) * forward.y * this.enginePower;\n\t\tbody.velocity.z += (velLength1 * this.lastDrag + speedModifier) * forward.z * this.enginePower;\n\n\t\t// document.getElementById('car-debug').innerHTML = 'Speed: ' + Utils.round(currentSpeed, 2) + '';\n\t\t// document.getElementById('car-debug').innerHTML += '<br>' + 'Power output: ' + Utils.round(velLength1 * this.lastDrag, 2) + '';\n\n\t\t// Drag\n\t\tlet velLength2 = body.velocity.length();\n\t\tconst drag = Math.pow(velLength2, 1) * 0.003 * this.enginePower;\n\t\tbody.velocity.x -= body.velocity.x * drag;\n\t\tbody.velocity.y -= body.velocity.y * drag;\n\t\tbody.velocity.z -= body.velocity.z * drag;\n\t\tthis.lastDrag = drag;\n\n\t\t// Lift\n\t\tlet lift = Math.pow(velLength2, 1) * 0.005 * this.enginePower;\n\t\tlift = THREE.MathUtils.clamp(lift, 0, 0.05);\n\t\tbody.velocity.x += up.x * lift;\n\t\tbody.velocity.y += up.y * lift;\n\t\tbody.velocity.z += up.z * lift;\n\n\t\t// Gravity\n\t\t// body.velocity.y -= 0.1;\n\n\t\t// document.getElementById('car-debug').innerHTML += '<br>' + 'Drag: ' + Utils.round(drag, 3) + '';\n\t\t// document.getElementById('car-debug').innerHTML += '<br>' + 'Lift: ' + Utils.round(lift, 3) + '';\n\n\t\t// Angular damping\n\t\tbody.angularVelocity.x = THREE.MathUtils.lerp(body.angularVelocity.x, body.angularVelocity.x * 0.98, flightModeInfluence);\n\t\tbody.angularVelocity.y = THREE.MathUtils.lerp(body.angularVelocity.y, body.angularVelocity.y * 0.98, flightModeInfluence);\n\t\tbody.angularVelocity.z = THREE.MathUtils.lerp(body.angularVelocity.z, body.angularVelocity.z * 0.98, flightModeInfluence);\n\t}\n\n\tpublic onInputChange(): void\n\t{\n\t\tsuper.onInputChange();\n\n\t\tconst brakeForce = 100;\n\n\t\tif (this.actions.exitVehicle.justPressed && this.controllingCharacter !== undefined)\n\t\t{\n\t\t\tthis.forceCharacterOut();\n\t\t}\n\t\tif (this.actions.wheelBrake.justPressed)\n\t\t{\n\t\t\tthis.setBrake(brakeForce);\n\t\t}\n\t\tif (this.actions.wheelBrake.justReleased)\n\t\t{\n\t\t\tthis.setBrake(0);\n\t\t}\n\t\tif (this.actions.view.justPressed)\n\t\t{\n\t\t\tthis.toggleFirstPersonView();\n\t\t}\n\t}\n\n\tpublic readAirplaneData(gltf: any): void\n\t{\n\t\tgltf.scene.traverse((child) => {\n\t\t\tif (child.hasOwnProperty('userData'))\n\t\t\t{\n\t\t\t\tif (child.userData.hasOwnProperty('data'))\n\t\t\t\t{\n\t\t\t\t\tif (child.userData.data === 'rotor')\n\t\t\t\t\t{\n\t\t\t\t\t\tthis.rotor = child;\n\t\t\t\t\t}\n\t\t\t\t\tif (child.userData.data === 'rudder')\n\t\t\t\t\t{\n\t\t\t\t\t\tthis.rudder = child;\n\t\t\t\t\t}\n\t\t\t\t\tif (child.userData.data === 'elevator')\n\t\t\t\t\t{\n\t\t\t\t\t\tthis.elevators.push(child);\n\t\t\t\t\t}\n\t\t\t\t\tif (child.userData.data === 'aileron')\n\t\t\t\t\t{\n\t\t\t\t\t\tif (child.userData.hasOwnProperty('side')) \n\t\t\t\t\t\t{\n\t\t\t\t\t\t\tif (child.userData.side === 'left')\n\t\t\t\t\t\t\t{\n\t\t\t\t\t\t\t\tthis.leftAileron = child;\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\telse if (child.userData.side === 'right')\n\t\t\t\t\t\t\t{\n\t\t\t\t\t\t\t\tthis.rightAileron = child;\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t});\n\t}\n\n\tpublic inputReceiverInit(): void\n\t{\n\t\tsuper.inputReceiverInit();\n\n\t\tthis.world.updateControls([\n\t\t\t{\n\t\t\t\tkeys: ['Shift'],\n\t\t\t\tdesc: '가속'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['Space'],\n\t\t\t\tdesc: '감속'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['W', 'S'],\n\t\t\t\tdesc: '상승 / 하강 조종'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['A', 'D'],\n\t\t\t\tdesc: '좌우 기울이기'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['Q', 'E'],\n\t\t\t\tdesc: '방향타 / 방향 조절'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['B'],\n\t\t\t\tdesc: '제동'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['V'],\n\t\t\t\tdesc: '시점 전환'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['F'],\n\t\t\t\tdesc: '내리기'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['Shift', '+', 'R'],\n\t\t\t\tdesc: '다시 출발'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['Shift', '+', 'C'],\n\t\t\t\tdesc: '자유 카메라'\n\t\t\t},\n\t\t]);\n\t}\n}", "src/ts/vehicles/Car.ts": "import * as CANNON from 'cannon';\n\nimport { Vehicle } from './Vehicle';\nimport { IControllable } from '../interfaces/IControllable';\nimport { KeyBinding } from '../core/KeyBinding';\nimport * as THREE from 'three';\nimport * as Utils from '../core/FunctionLibrary';\nimport { SpringSimulator } from '../physics/spring_simulation/SpringSimulator';\nimport { World } from '../world/World';\nimport { EntityType } from '../enums/EntityType';\n\nexport class Car extends Vehicle implements IControllable\n{\n\tpublic entityType: EntityType = EntityType.Car;\n\tpublic drive: string = 'awd';\n\tget speed(): number {\n\t\treturn this._speed;\n\t}\n\tprivate _speed: number = 0;\n\n\t// private wheelsDebug: THREE.Mesh[] = [];\n\tprivate steeringWheel: THREE.Object3D;\n\tprivate airSpinTimer: number = 0;\n\n\tprivate steeringSimulator: SpringSimulator;\n\tprivate gear: number = 1;\n\n\t// Transmission\n\tprivate shiftTimer: number;\n\tprivate timeToShift: number = 0.2;\n\n\tprivate canTiltForwards: boolean = false;\n\tprivate characterWantsToExit: boolean = false;\n\n\tconstructor(gltf: any)\n\t{\n\t\tsuper(gltf, {\n\t\t\tradius: 0.25,\n\t\t\tsuspensionStiffness: 20,\n\t\t\tsuspensionRestLength: 0.35,\n\t\t\tmaxSuspensionTravel: 1,\n\t\t\tfrictionSlip: 0.8,\n\t\t\tdampingRelaxation: 2,\n\t\t\tdampingCompression: 2,\n\t\t\trollInfluence: 0.8\n\t\t});\n\n\t\tthis.readCarData(gltf);\n\n\t\tthis.collision.preStep = (body: CANNON.Body) => { this.physicsPreStep(body, this); };\n\n\t\tthis.actions = {\n\t\t\t'throttle': new KeyBinding('KeyW'),\n\t\t\t'reverse': new KeyBinding('KeyS'),\n\t\t\t'brake': new KeyBinding('Space'),\n\t\t\t'left': new KeyBinding('KeyA'),\n\t\t\t'right': new KeyBinding('KeyD'),\n\t\t\t'exitVehicle': new KeyBinding('KeyF'),\n\t\t\t'seat_switch': new KeyBinding('KeyX'),\n\t\t\t'view': new KeyBinding('KeyV'),\n\t\t};\n\n\t\tthis.steeringSimulator = new SpringSimulator(60, 10, 0.6);\n\t}\n\n\tpublic noDirectionPressed(): boolean\n\t{\n\t\tlet result = \n\t\t!this.actions.throttle.isPressed &&\n\t\t!this.actions.reverse.isPressed &&\n\t\t!this.actions.left.isPressed &&\n\t\t!this.actions.right.isPressed;\n\n\t\treturn result;\n\t}\n\n\tpublic update(timeStep: number): void\n\t{\n\t\tsuper.update(timeStep);\n\n\t\tconst tiresHaveContact = this.rayCastVehicle.numWheelsOnGround > 0;\n\n\t\t// Air spin\n\t\tif (!tiresHaveContact)\n\t\t{\n\t\t\t// Timer grows when car is off ground, resets once you touch the ground again\n\t\t\tthis.airSpinTimer += timeStep;\n\t\t\tif (!this.actions.throttle.isPressed) this.canTiltForwards = true;\n\t\t}\n\t\telse\n\t\t{\n\t\t\tthis.canTiltForwards = false;\n\t\t\tthis.airSpinTimer = 0;\n\t\t}\n\n\t\t// Engine\n\t\tconst engineForce = 500;\n\t\tconst maxGears = 5;\n\t\tconst gearsMaxSpeeds = {\n\t\t\t'R': -4,\n\t\t\t'0': 0,\n\t\t\t'1': 5,\n\t\t\t'2': 9,\n\t\t\t'3': 13,\n\t\t\t'4': 17,\n\t\t\t'5': 22,\n\t\t};\n\n\t\tif (this.shiftTimer > 0)\n\t\t{\n\t\t\tthis.shiftTimer -= timeStep;\n\t\t\tif (this.shiftTimer < 0) this.shiftTimer = 0;\n\t\t}\n\t\telse\n\t\t{\n\t\t\t// Transmission \n\t\t\tif (this.actions.reverse.isPressed)\n\t\t\t{\n\t\t\t\tconst powerFactor = (gearsMaxSpeeds['R'] - this.speed) / Math.abs(gearsMaxSpeeds['R']);\n\t\t\t\tconst force = (engineForce / this.gear) * (Math.abs(powerFactor) ** 1);\n\n\t\t\t\tthis.applyEngineForce(force);\n\t\t\t}\n\t\t\telse\n\t\t\t{\n\t\t\t\tconst powerFactor = (gearsMaxSpeeds[this.gear] - this.speed) / (gearsMaxSpeeds[this.gear] - gearsMaxSpeeds[this.gear - 1]);\n\n\t\t\t\tif (powerFactor < 0.1 && this.gear < maxGears) this.shiftUp();\n\t\t\t\telse if (this.gear > 1 && powerFactor > 1.2) this.shiftDown();\n\t\t\t\telse if (this.actions.throttle.isPressed)\n\t\t\t\t{\n\t\t\t\t\tconst force = (engineForce / this.gear) * (powerFactor ** 1);\n\t\t\t\t\tthis.applyEngineForce(-force);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\n\t\t// Steering\n\t\tthis.steeringSimulator.simulate(timeStep);\n\t\tthis.setSteeringValue(this.steeringSimulator.position);\n\t\tif (this.steeringWheel !== undefined) this.steeringWheel.rotation.z = -this.steeringSimulator.position * 2;\n\n\t\tif (this.rayCastVehicle.numWheelsOnGround < 3 && Math.abs(this.collision.velocity.length()) < 0.5)\t\n\t\t{\t\n\t\t\tthis.collision.quaternion.copy(this.collision.initQuaternion);\t\n\t\t}\n\n\t\t// Getting out\n\t\tif (this.characterWantsToExit && this.controllingCharacter !== undefined && this.controllingCharacter.charState.canLeaveVehicles)\n\t\t{\n\t\t\tlet speed = this.collision.velocity.length();\n\n\t\t\tif (speed > 0.1 && speed < 4)\n\t\t\t{\n\t\t\t\tthis.triggerAction('brake', true);\n\t\t\t}\n\t\t\telse\n\t\t\t{\n\t\t\t\tthis.forceCharacterOut();\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic shiftUp(): void\n\t{\n\t\tthis.gear++;\n\t\tthis.shiftTimer = this.timeToShift;\n\n\t\tthis.applyEngineForce(0);\n\t}\n\n\tpublic shiftDown(): void\n\t{\n\t\tthis.gear--;\n\t\tthis.shiftTimer = this.timeToShift;\n\n\t\tthis.applyEngineForce(0);\n\t}\n\n\tpublic physicsPreStep(body: CANNON.Body, car: Car): void\n\t{\n\t\t// Constants\n\t\tconst quat = Utils.threeQuat(body.quaternion);\n\t\tconst forward = new THREE.Vector3(0, 0, 1).applyQuaternion(quat);\n\t\tconst right = new THREE.Vector3(1, 0, 0).applyQuaternion(quat);\n\t\tconst up = new THREE.Vector3(0, 1, 0).applyQuaternion(quat);\n\n\t\t// Measure speed\n\t\tthis._speed = this.collision.velocity.dot(Utils.cannonVector(forward));\n\n\t\t// Air spin\n\t\t// It takes 2 seconds until you have max spin air control since you leave the ground\n\t\tlet airSpinInfluence = THREE.MathUtils.clamp(this.airSpinTimer / 2, 0, 1);\n\t\tairSpinInfluence *= THREE.MathUtils.clamp(this.speed, 0, 1);\n\t\t\n\t\tconst flipSpeedFactor = THREE.MathUtils.clamp(1 - this.speed, 0, 1);\n\t\tconst upFactor = (up.dot(new THREE.Vector3(0, -1, 0)) / 2) + 0.5;\n\t\tconst flipOverInfluence = flipSpeedFactor * upFactor * 3;\n\n\t\tconst maxAirSpinMagnitude = 2.0;\n\t\tconst airSpinAcceleration = 0.15;\n\t\tconst angVel = this.collision.angularVelocity;\n\n\t\tconst spinVectorForward = Utils.cannonVector(forward.clone());\n\t\tconst spinVectorRight = Utils.cannonVector(right.clone());\n\n\t\tconst effectiveSpinVectorForward = Utils.cannonVector(forward.clone().multiplyScalar(airSpinAcceleration * (airSpinInfluence + flipOverInfluence)));\n\t\tconst effectiveSpinVectorRight = Utils.cannonVector(right.clone().multiplyScalar(airSpinAcceleration * (airSpinInfluence)));\n\n\t\t// Right\n\t\tif (this.actions.right.isPressed && !this.actions.left.isPressed) {\n\t\t\tif (angVel.dot(spinVectorForward) < maxAirSpinMagnitude) {\n\t\t\t\tangVel.vadd(effectiveSpinVectorForward, angVel);\n\t\t\t}\n\t\t} else\n\t\t// Left\n\t\tif (this.actions.left.isPressed && !this.actions.right.isPressed) {\n\t\t\tif (angVel.dot(spinVectorForward) > -maxAirSpinMagnitude) {\n\t\t\t\tangVel.vsub(effectiveSpinVectorForward, angVel);\n\t\t\t}\n\t\t}\n\n\t\t// Forwards\n\t\tif (this.canTiltForwards && this.actions.throttle.isPressed && !this.actions.reverse.isPressed) {\n\t\t\tif (angVel.dot(spinVectorRight) < maxAirSpinMagnitude) {\n\t\t\t\tangVel.vadd(effectiveSpinVectorRight, angVel);\n\t\t\t}\n\t\t} else\n\t\t// Backwards\n\t\tif (this.actions.reverse.isPressed && !this.actions.throttle.isPressed) {\n\t\t\tif (angVel.dot(spinVectorRight) > -maxAirSpinMagnitude) {\n\t\t\t\tangVel.vsub(effectiveSpinVectorRight, angVel);\n\t\t\t}\n\t\t}\n\n\t\t// Steering\n\t\tconst velocity = new CANNON.Vec3().copy(this.collision.velocity);\n\t\tvelocity.normalize();\n\t\tlet driftCorrection = Utils.getSignedAngleBetweenVectors(Utils.threeVector(velocity), forward);\n\n\t\tconst maxSteerVal = 0.8;\n\t\tlet speedFactor = THREE.MathUtils.clamp(this.speed * 0.3, 1, Number.MAX_VALUE);\n\n\t\tif (this.actions.right.isPressed)\n\t\t{\n\t\t\tlet steering = Math.min(-maxSteerVal / speedFactor, -driftCorrection);\n\t\t\tthis.steeringSimulator.target = THREE.MathUtils.clamp(steering, -maxSteerVal, maxSteerVal);\n\t\t}\n\t\telse if (this.actions.left.isPressed)\n\t\t{\n\t\t\tlet steering = Math.max(maxSteerVal / speedFactor, -driftCorrection);\n\t\t\tthis.steeringSimulator.target = THREE.MathUtils.clamp(steering, -maxSteerVal, maxSteerVal);\n\t\t}\n\t\telse this.steeringSimulator.target = 0;\n\n\t\t// Update doors\n\t\tthis.seats.forEach((seat) => {\n\t\t\tseat.door?.preStepCallback();\n\t\t});\n\t}\n\n\tpublic onInputChange(): void {\n\t\tsuper.onInputChange();\n\n\t\tconst brakeForce = 1000000;\n\n\t\tif (this.actions.exitVehicle.justPressed)\n\t\t{\n\t\t\tthis.characterWantsToExit = true;\n\t\t}\n\t\tif (this.actions.exitVehicle.justReleased)\n\t\t{\n\t\t\tthis.characterWantsToExit = false;\n\t\t\tthis.triggerAction('brake', false);\n\t\t}\n\t\tif (this.actions.throttle.justReleased || this.actions.reverse.justReleased)\n\t\t{\n\t\t\tthis.applyEngineForce(0);\n\t\t}\n\t\tif (this.actions.brake.justPressed)\n\t\t{\n\t\t\tthis.setBrake(brakeForce, 'rwd');\n\t\t}\n\t\tif (this.actions.brake.justReleased)\n\t\t{\n\t\t\tthis.setBrake(0, 'rwd');\n\t\t}\n\t\tif (this.actions.view.justPressed)\n\t\t{\n\t\t\tthis.toggleFirstPersonView();\n\t\t}\n\t}\n\n\tpublic inputReceiverInit(): void\n\t{\n\t\tsuper.inputReceiverInit();\n\n\t\tthis.world.updateControls([\n\t\t\t{\n\t\t\t\tkeys: ['W', 'S'],\n\t\t\t\tdesc: '가속, 제동 / 후진'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['A', 'D'],\n\t\t\t\tdesc: '방향 조절'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['Space'],\n\t\t\t\tdesc: '주차 브레이크'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['V'],\n\t\t\t\tdesc: '시점 전환'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['F'],\n\t\t\t\tdesc: '내리기'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['Shift', '+', 'R'],\n\t\t\t\tdesc: '다시 출발'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['Shift', '+', 'C'],\n\t\t\t\tdesc: '자유 카메라'\n\t\t\t},\n\t\t]);\n\t}\n\n\tpublic readCarData(gltf: any): void\n\t{\n\t\tgltf.scene.traverse((child: THREE.Object3D) => {\n\t\t\tif (child.hasOwnProperty('userData'))\n\t\t\t{\n\t\t\t\tif (child.userData.hasOwnProperty('data'))\n\t\t\t\t{\n\t\t\t\t\tif (child.userData.data === 'steering_wheel')\n\t\t\t\t\t{\n\t\t\t\t\t\tthis.steeringWheel = child;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t});\n\t}\n}", "src/ts/vehicles/Helicopter.ts": "import * as THREE from 'three';\nimport * as CANNON from 'cannon';\nimport * as Utils from '../core/FunctionLibrary';\n\nimport { Vehicle } from './Vehicle';\nimport { IControllable } from '../interfaces/IControllable';\nimport { IWorldEntity } from '../interfaces/IWorldEntity';\nimport { KeyBinding } from '../core/KeyBinding';\nimport { World } from '../world/World';\nimport { EntityType } from '../enums/EntityType';\n\nexport class Helicopter extends Vehicle implements IControllable, IWorldEntity\n{\n\tpublic entityType: EntityType = EntityType.Helicopter;\n\tpublic rotors: THREE.Object3D[] = [];\n\tprivate enginePower: number = 0;\n\n\tconstructor(gltf: any)\n\t{\n\t\tsuper(gltf);\n\n\t\tthis.readHelicopterData(gltf);\n\n\t\tthis.collision.preStep = (body: CANNON.Body) => { this.physicsPreStep(body, this); };\n\n\t\tthis.actions = {\n\t\t\t'ascend': new KeyBinding('ShiftLeft'),\n\t\t\t'descend': new KeyBinding('Space'),\n\t\t\t'pitchUp': new KeyBinding('KeyS'),\n\t\t\t'pitchDown': new KeyBinding('KeyW'),\n\t\t\t'yawLeft': new KeyBinding('KeyQ'),\n\t\t\t'yawRight': new KeyBinding('KeyE'),\n\t\t\t'rollLeft': new KeyBinding('KeyA'),\n\t\t\t'rollRight': new KeyBinding('KeyD'),\n\t\t\t'exitVehicle': new KeyBinding('KeyF'),\n\t\t\t'seat_switch': new KeyBinding('KeyX'),\n\t\t\t'view': new KeyBinding('KeyV'),\n\t\t};\n\t}\n\n\tpublic noDirectionPressed(): boolean\n\t{\n\t\tlet result = \n\t\t!this.actions.ascend.isPressed &&\n\t\t!this.actions.descend.isPressed;\n\n\t\treturn result;\n\t}\n\n\tpublic update(timeStep: number): void\n\t{\n\t\tsuper.update(timeStep);\n\t\t\n\t\t// Rotors visuals\n\t\tif (this.controllingCharacter !== undefined)\n\t\t{\n\t\t\tif (this.enginePower < 1) this.enginePower += timeStep * 0.2;\n\t\t\tif (this.enginePower > 1) this.enginePower = 1;\n\t\t}\n\t\telse\n\t\t{\n\t\t\tif (this.enginePower > 0) this.enginePower -= timeStep * 0.06;\n\t\t\tif (this.enginePower < 0) this.enginePower = 0;\n\t\t}\n\n\t\tthis.rotors.forEach((rotor) =>\n\t\t{\n\t\t\trotor.rotateX(this.enginePower * timeStep * 30);\n\t\t});\n\t}\n\n\tpublic onInputChange(): void\n\t{\n\t\tsuper.onInputChange();\n\n\t\tif (this.actions.exitVehicle.justPressed && this.controllingCharacter !== undefined)\n\t\t{\n\t\t\tthis.forceCharacterOut();\n\t\t}\n\t\tif (this.actions.view.justPressed)\n\t\t{\n\t\t\tthis.toggleFirstPersonView();\n\t\t}\n\t}\n\n\tpublic physicsPreStep(body: CANNON.Body, heli: Helicopter): void\n\t{\n\t\tlet quat = Utils.threeQuat(body.quaternion);\n\t\tlet right = new THREE.Vector3(1, 0, 0).applyQuaternion(quat);\n\t\tlet globalUp = new THREE.Vector3(0, 1, 0);\n\t\tlet up = new THREE.Vector3(0, 1, 0).applyQuaternion(quat);\n\t\tlet forward = new THREE.Vector3(0, 0, 1).applyQuaternion(quat);\n\t\t\n\t\t// Throttle\n\t\tif (heli.actions.ascend.isPressed)\n\t\t{\n\t\t\tbody.velocity.x += up.x * 0.15 * this.enginePower;\n\t\t\tbody.velocity.y += up.y * 0.15 * this.enginePower;\n\t\t\tbody.velocity.z += up.z * 0.15 * this.enginePower;\n\t\t}\n\t\tif (heli.actions.descend.isPressed)\n\t\t{\n\t\t\tbody.velocity.x -= up.x * 0.15 * this.enginePower;\n\t\t\tbody.velocity.y -= up.y * 0.15 * this.enginePower;\n\t\t\tbody.velocity.z -= up.z * 0.15 * this.enginePower;\n\t\t}\n\n\t\t// Vertical stabilization\n\t\tlet gravity = heli.world.physicsWorld.gravity;\n\t\tlet gravityCompensation = new CANNON.Vec3(-gravity.x, -gravity.y, -gravity.z).length();\n\t\tgravityCompensation *= heli.world.physicsFrameTime;\n\t\tgravityCompensation *= 0.98;\n\t\tlet dot = globalUp.dot(up);\n\t\tgravityCompensation *= Math.sqrt(THREE.MathUtils.clamp(dot, 0, 1));\n\n\t\tlet vertDamping = new THREE.Vector3(0, body.velocity.y, 0).multiplyScalar(-0.01);\n\t\tlet vertStab = up.clone();\n\t\tvertStab.multiplyScalar(gravityCompensation);\n\t\tvertStab.add(vertDamping);\n\t\tvertStab.multiplyScalar(heli.enginePower);\n\n\t\tbody.velocity.x += vertStab.x;\n\t\tbody.velocity.y += vertStab.y;\n\t\tbody.velocity.z += vertStab.z;\n\n\t\t// Positional damping\n\t\tbody.velocity.x *= THREE.MathUtils.lerp(1, 0.995, this.enginePower);\n\t\tbody.velocity.z *= THREE.MathUtils.lerp(1, 0.995, this.enginePower);\n\n\t\t// Rotation stabilization\n\t\tif (this.controllingCharacter !== undefined)\n\t\t{\n\t\t\tlet rotStabVelocity = new THREE.Quaternion().setFromUnitVectors(up, globalUp);\n\t\t\trotStabVelocity.x *= 0.3;\n\t\t\trotStabVelocity.y *= 0.3;\n\t\t\trotStabVelocity.z *= 0.3;\n\t\t\trotStabVelocity.w *= 0.3;\n\t\t\tlet rotStabEuler = new THREE.Euler().setFromQuaternion(rotStabVelocity);\n\t\t\t\n\t\t\tbody.angularVelocity.x += rotStabEuler.x * this.enginePower;\n\t\t\tbody.angularVelocity.y += rotStabEuler.y * this.enginePower;\n\t\t\tbody.angularVelocity.z += rotStabEuler.z * this.enginePower;\n\t\t}\n\n\t\t// Pitch\n\t\tif (heli.actions.pitchUp.isPressed)\n\t\t{\n\t\t\tbody.angularVelocity.x -= right.x * 0.07 * this.enginePower;\n\t\t\tbody.angularVelocity.y -= right.y * 0.07 * this.enginePower;\n\t\t\tbody.angularVelocity.z -= right.z * 0.07 * this.enginePower;\n\t\t}\n\t\tif (heli.actions.pitchDown.isPressed)\n\t\t{\n\t\t\tbody.angularVelocity.x += right.x * 0.07 * this.enginePower;\n\t\t\tbody.angularVelocity.y += right.y * 0.07 * this.enginePower;\n\t\t\tbody.angularVelocity.z += right.z * 0.07 * this.enginePower;\n\t\t}\n\n\t\t// Yaw\n\t\tif (heli.actions.yawLeft.isPressed)\n\t\t{\n\t\t\tbody.angularVelocity.x += up.x * 0.07 * this.enginePower;\n\t\t\tbody.angularVelocity.y += up.y * 0.07 * this.enginePower;\n\t\t\tbody.angularVelocity.z += up.z * 0.07 * this.enginePower;\n\t\t}\n\t\tif (heli.actions.yawRight.isPressed)\n\t\t{\n\t\t\tbody.angularVelocity.x -= up.x * 0.07 * this.enginePower;\n\t\t\tbody.angularVelocity.y -= up.y * 0.07 * this.enginePower;\n\t\t\tbody.angularVelocity.z -= up.z * 0.07 * this.enginePower;\n\t\t}\n\n\t\t// Roll\n\t\tif (heli.actions.rollLeft.isPressed)\n\t\t{\n\t\t\tbody.angularVelocity.x -= forward.x * 0.07 * this.enginePower;\n\t\t\tbody.angularVelocity.y -= forward.y * 0.07 * this.enginePower;\n\t\t\tbody.angularVelocity.z -= forward.z * 0.07 * this.enginePower;\n\t\t}\n\t\tif (heli.actions.rollRight.isPressed)\n\t\t{\n\t\t\tbody.angularVelocity.x += forward.x * 0.07 * this.enginePower;\n\t\t\tbody.angularVelocity.y += forward.y * 0.07 * this.enginePower;\n\t\t\tbody.angularVelocity.z += forward.z * 0.07 * this.enginePower;\n\t\t}\n\n\t\t// Angular damping\n\t\tbody.angularVelocity.x *= 0.97;\n\t\tbody.angularVelocity.y *= 0.97;\n\t\tbody.angularVelocity.z *= 0.97;\n\t}\n\n\tpublic readHelicopterData(gltf: any): void\n\t{\n\t\tgltf.scene.traverse((child) => {\n\t\t\tif (child.hasOwnProperty('userData'))\n\t\t\t{\n\t\t\t\tif (child.userData.hasOwnProperty('data'))\n\t\t\t\t{\n\t\t\t\t\tif (child.userData.data === 'rotor')\n\t\t\t\t\t{\n\t\t\t\t\t\tthis.rotors.push(child);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t});\n\t}\n\n\tpublic inputReceiverInit(): void\n\t{\n\t\tsuper.inputReceiverInit();\n\n\t\tthis.world.updateControls([\n\t\t\t{\n\t\t\t\tkeys: ['Shift'],\n\t\t\t\tdesc: '상승'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['Space'],\n\t\t\t\tdesc: '하강'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['W', 'S'],\n\t\t\t\tdesc: '앞뒤 기울이기'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['Q', 'E'],\n\t\t\t\tdesc: '좌우 회전'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['A', 'D'],\n\t\t\t\tdesc: '좌우 기울이기'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['V'],\n\t\t\t\tdesc: '시점 전환'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['F'],\n\t\t\t\tdesc: '내리기'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['Shift', '+', 'R'],\n\t\t\t\tdesc: '다시 출발'\n\t\t\t},\n\t\t\t{\n\t\t\t\tkeys: ['Shift', '+', 'C'],\n\t\t\t\tdesc: '자유 카메라'\n\t\t\t},\n\t\t]);\n\t}\n}", "src/ts/world/Scenario.ts": "import { ISpawnPoint } from '../interfaces/ISpawnPoint';\nimport { VehicleSpawnPoint } from './VehicleSpawnPoint';\nimport { CharacterSpawnPoint } from './CharacterSpawnPoint';\nimport { World } from '../world/World';\nimport { LoadingManager } from '../core/LoadingManager';\n\nexport class Scenario\n{\n\tpublic id: string;\n\tpublic name: string;\n\tpublic spawnAlways: boolean = false;\n\tpublic default: boolean = false;\n\tpublic world: World;\n\tpublic descriptionTitle: string;\n\tpublic descriptionContent: string;\n\t\n\tprivate rootNode: THREE.Object3D;\n\tprivate spawnPoints: ISpawnPoint[] = [];\n\tprivate invisible: boolean = false;\n\tprivate initialCameraAngle: number;\n\n\tconstructor(root: THREE.Object3D, world: World)\n\t{\n\t\tconst ko: {[key: string]: string} = {\"Oval race\": \"타원형 트랙 경주\", \"Tunnel race\": \"터널 경주\", \"Figure 8 race\": \"8자 트랙 경주\", \"Loop ramp\": \"루프 경사로\", \"Mega ramp\": \"초대형 경사로\", \"Free roam (default)\": \"자유 탐험 (기본)\", \"Default spawn\": \"자유 탐험\", \"Free roam (aviation)\": \"자유 탐험 (항공)\", \"Aviation spawn\": \"항공기 체험\", \"Explore the world!\": \"세계를 자유롭게 탐험해 보세요!\", \"Try out Sketchbook's custom airplane and helicopter physics.\": \"Sketchbook의 비행기와 헬리콥터 물리를 체험해 보세요.\", \"Race around the oval against opponents. There's no lap or position tracking yet, so just enjoy the ride for now. :)\": \"상대 차량과 타원형 트랙을 달립니다. 아직 랩 수와 순위 기록은 없으니 주행을 즐겨 주세요. :)\", \"Race through the tunnels against opponents. Turn around when you reach either of the Spomenik monuments. There's no lap or position tracking yet, so just enjoy the ride for now. :)\": \"상대 차량과 터널을 달립니다. 양끝의 스포메니크 기념물에 도착하면 돌아오세요. 아직 랩 수와 순위 기록은 없습니다. :)\", \"Race around the track against opponents. There's no lap or position tracking yet, so just enjoy the ride for now. :)\": \"상대 차량과 트랙을 달립니다. 아직 랩 수와 순위 기록은 없으니 주행을 즐겨 주세요. :)\", \"Make it around the loop and climb up the other side. Try letting off the gas pedal when you drive down the ramp, as the car won't get limited by the engine's maximum RPM.\": \"루프를 돌아 반대편으로 올라가 보세요. 경사로를 내려갈 때 가속 키를 놓으면 엔진 최고 회전수에 속도가 제한되지 않습니다.\", \"Drive down the mega ramp! Can you make it down in one piece?\": \"초대형 경사로를 내려가세요! 무사히 도착할 수 있을까요?\"};\n\t\tfor (const key of ['name', 'desc_title', 'desc_content']) { if (ko[root.userData[key]]) root.userData[key] = ko[root.userData[key]]; }\n\t\tthis.rootNode = root;\n\t\tthis.world = world;\n\t\tthis.id = root.name;\n\n\t\t// Scenario\n\t\tif (root.userData.hasOwnProperty('name')) \n\t\t{\n\t\t\tthis.name = root.userData.name;\n\t\t}\n\t\tif (root.userData.hasOwnProperty('default') && root.userData.default === 'true') \n\t\t{\n\t\t\tthis.default = true;\n\t\t}\n\t\tif (root.userData.hasOwnProperty('spawn_always') && root.userData.spawn_always === 'true') \n\t\t{\n\t\t\tthis.spawnAlways = true;\n\t\t}\n\t\tif (root.userData.hasOwnProperty('invisible') && root.userData.invisible === 'true') \n\t\t{\n\t\t\tthis.invisible = true;\n\t\t}\n\t\tif (root.userData.hasOwnProperty('desc_title')) \n\t\t{\n\t\t\tthis.descriptionTitle = root.userData.desc_title;\n\t\t}\n\t\tif (root.userData.hasOwnProperty('desc_content')) \n\t\t{\n\t\t\tthis.descriptionContent = root.userData.desc_content;\n\t\t}\n\t\tif (root.userData.hasOwnProperty('camera_angle')) \n\t\t{\n\t\t\tthis.initialCameraAngle = root.userData.camera_angle;\n\t\t}\n\n\t\tif (!this.invisible) this.createLaunchLink();\n\n\t\t// Find all scenario spawns and enitites\n\t\troot.traverse((child) => {\n\t\t\tif (child.hasOwnProperty('userData') && child.userData.hasOwnProperty('data'))\n\t\t\t{\n\t\t\t\tif (child.userData.data === 'spawn')\n\t\t\t\t{\n\t\t\t\t\tif (child.userData.type === 'car' || child.userData.type === 'airplane' || child.userData.type === 'heli')\n\t\t\t\t\t{\n\t\t\t\t\t\tlet sp = new VehicleSpawnPoint(child);\n\n\t\t\t\t\t\tif (child.userData.hasOwnProperty('type')) \n\t\t\t\t\t\t{\n\t\t\t\t\t\t\tsp.type = child.userData.type;\n\t\t\t\t\t\t}\n\n\t\t\t\t\t\tif (child.userData.hasOwnProperty('driver')) \n\t\t\t\t\t\t{\n\t\t\t\t\t\t\tsp.driver = child.userData.driver;\n\n\t\t\t\t\t\t\tif (child.userData.driver === 'ai' && child.userData.hasOwnProperty('first_node'))\n\t\t\t\t\t\t\t{\n\t\t\t\t\t\t\t\tsp.firstAINode = child.userData.first_node;\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t}\n\n\t\t\t\t\t\tthis.spawnPoints.push(sp);\n\t\t\t\t\t}\n\t\t\t\t\telse if (child.userData.type === 'player')\n\t\t\t\t\t{\n\t\t\t\t\t\tlet sp = new CharacterSpawnPoint(child);\n\t\t\t\t\t\tthis.spawnPoints.push(sp);\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t});\n\t}\n\n\tpublic createLaunchLink(): void\n\t{\n\t\tthis.world.params[this.name] = () =>\n\t\t{\n\t\t\tthis.world.launchScenario(this.id);\n\t\t};\n\t\tthis.world.scenarioGUIFolder.add(this.world.params, this.name);\n\t}\n\n\tpublic launch(loadingManager: LoadingManager, world: World): void\n\t{\n\t\tthis.spawnPoints.forEach((sp) => {\n\t\t\tsp.spawn(loadingManager, world);\n\t\t});\n\n\t\tif (!this.spawnAlways)\n\t\t{\n\t\t\tloadingManager.createWelcomeScreenCallback(this);\n\n\t\t\tworld.cameraOperator.theta = this.initialCameraAngle;\n\t\t\tworld.cameraOperator.phi = 15;\n\t\t}\n\t}\n}", "src/ts/world/World.ts": "import * as THREE from 'three';\nimport * as CANNON from 'cannon';\nimport Swal from 'sweetalert2';\nimport * as $ from 'jquery';\n\nimport { CameraOperator } from '../core/CameraOperator';\nimport { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer';\nimport { RenderPass } from 'three/examples/jsm/postprocessing/RenderPass';\nimport { ShaderPass } from 'three/examples/jsm/postprocessing/ShaderPass';\nimport { FXAAShader  } from 'three/examples/jsm/shaders/FXAAShader';\n\nimport { Detector } from '../../lib/utils/Detector';\nimport { Stats } from '../../lib/utils/Stats';\nimport * as GUI from '../../lib/utils/dat.gui';\nimport { CannonDebugRenderer } from '../../lib/cannon/CannonDebugRenderer';\nimport * as _ from 'lodash';\n\nimport { InputManager } from '../core/InputManager';\nimport * as Utils from '../core/FunctionLibrary';\nimport { LoadingManager } from '../core/LoadingManager';\nimport { InfoStack } from '../core/InfoStack';\nimport { UIManager } from '../core/UIManager';\nimport { IWorldEntity } from '../interfaces/IWorldEntity';\nimport { IUpdatable } from '../interfaces/IUpdatable';\nimport { Character } from '../characters/Character';\nimport { Path } from './Path';\nimport { CollisionGroups } from '../enums/CollisionGroups';\nimport { BoxCollider } from '../physics/colliders/BoxCollider';\nimport { TrimeshCollider } from '../physics/colliders/TrimeshCollider';\nimport { Vehicle } from '../vehicles/Vehicle';\nimport { Scenario } from './Scenario';\nimport { Sky } from './Sky';\nimport { Ocean } from './Ocean';\n\nexport class World\n{\n\tpublic renderer: THREE.WebGLRenderer;\n\tpublic camera: THREE.PerspectiveCamera;\n\tpublic composer: any;\n\tpublic stats: Stats;\n\tpublic graphicsWorld: THREE.Scene;\n\tpublic sky: Sky;\n\tpublic physicsWorld: CANNON.World;\n\tpublic parallelPairs: any[];\n\tpublic physicsFrameRate: number;\n\tpublic physicsFrameTime: number;\n\tpublic physicsMaxPrediction: number;\n\tpublic clock: THREE.Clock;\n\tpublic renderDelta: number;\n\tpublic logicDelta: number;\n\tpublic requestDelta: number;\n\tpublic sinceLastFrame: number;\n\tpublic justRendered: boolean;\n\tpublic params: any;\n\tpublic inputManager: InputManager;\n\tpublic cameraOperator: CameraOperator;\n\tpublic timeScaleTarget: number = 1;\n\tpublic console: InfoStack;\n\tpublic cannonDebugRenderer: CannonDebugRenderer;\n\tpublic scenarios: Scenario[] = [];\n\tpublic characters: Character[] = [];\n\tpublic vehicles: Vehicle[] = [];\n\tpublic paths: Path[] = [];\n\tpublic scenarioGUIFolder: any;\n\tpublic updatables: IUpdatable[] = [];\n\n\tprivate lastScenarioID: string;\n\n\tconstructor(worldScenePath?: any)\n\t{\n\t\tconst scope = this;\n\n\t\t// WebGL not supported\n\t\tif (!Detector.webgl)\n\t\t{\n\t\t\tSwal.fire({\n\t\t\t\ticon: 'warning',\n\t\t\t\ttitle: 'WebGL 호환성',\n\t\t\t\ttext: '이 브라우저에서는 필요한 WebGL 기능을 사용할 수 없어 정상적으로 실행되지 않을 수 있습니다.',\n\t\t\t\tfooter: '<a href=\"https://get.webgl.org/\" target=\"_blank\">자세히 알아보기</a>',\n\t\t\t\tshowConfirmButton: false,\n\t\t\t\tbuttonsStyling: false\n\t\t\t});\n\t\t}\n\n\t\t// Renderer\n\t\tthis.renderer = new THREE.WebGLRenderer();\n\t\tthis.renderer.setPixelRatio(window.devicePixelRatio);\n\t\tthis.renderer.setSize(window.innerWidth, window.innerHeight);\n\t\tthis.renderer.toneMapping = THREE.ACESFilmicToneMapping;\n\t\tthis.renderer.toneMappingExposure = 1.0;\n\t\tthis.renderer.shadowMap.enabled = true;\n\t\tthis.renderer.shadowMap.type = THREE.PCFSoftShadowMap;\n\n\t\tthis.generateHTML();\n\n\t\t// Auto window resize\n\t\tfunction onWindowResize(): void\n\t\t{\n\t\t\tscope.camera.aspect = window.innerWidth / window.innerHeight;\n\t\t\tscope.camera.updateProjectionMatrix();\n\t\t\tscope.renderer.setSize(window.innerWidth, window.innerHeight);\n\t\t\tfxaaPass.uniforms['resolution'].value.set(1 / (window.innerWidth * pixelRatio), 1 / (window.innerHeight * pixelRatio));\n\t\t\tscope.composer.setSize(window.innerWidth * pixelRatio, window.innerHeight * pixelRatio);\n\t\t}\n\t\twindow.addEventListener('resize', onWindowResize, false);\n\n\t\t// Three.js scene\n\t\tthis.graphicsWorld = new THREE.Scene();\n\t\tthis.camera = new THREE.PerspectiveCamera(80, window.innerWidth / window.innerHeight, 0.1, 1010);\n\n\t\t// Passes\n\t\tlet renderPass = new RenderPass( this.graphicsWorld, this.camera );\n\t\tlet fxaaPass = new ShaderPass( FXAAShader );\n\n\t\t// FXAA\n\t\tlet pixelRatio = this.renderer.getPixelRatio();\n\t\tfxaaPass.material['uniforms'].resolution.value.x = 1 / ( window.innerWidth * pixelRatio );\n\t\tfxaaPass.material['uniforms'].resolution.value.y = 1 / ( window.innerHeight * pixelRatio );\n\n\t\t// Composer\n\t\tthis.composer = new EffectComposer( this.renderer );\n\t\tthis.composer.addPass( renderPass );\n\t\tthis.composer.addPass( fxaaPass );\n\n\t\t// Physics\n\t\tthis.physicsWorld = new CANNON.World();\n\t\tthis.physicsWorld.gravity.set(0, -9.81, 0);\n\t\tthis.physicsWorld.broadphase = new CANNON.SAPBroadphase(this.physicsWorld);\n\t\tthis.physicsWorld.solver.iterations = 10;\n\t\tthis.physicsWorld.allowSleep = true;\n\n\t\tthis.parallelPairs = [];\n\t\tthis.physicsFrameRate = 60;\n\t\tthis.physicsFrameTime = 1 / this.physicsFrameRate;\n\t\tthis.physicsMaxPrediction = this.physicsFrameRate;\n\n\t\t// RenderLoop\n\t\tthis.clock = new THREE.Clock();\n\t\tthis.renderDelta = 0;\n\t\tthis.logicDelta = 0;\n\t\tthis.sinceLastFrame = 0;\n\t\tthis.justRendered = false;\n\n\t\t// Stats (FPS, Frame time, Memory)\n\t\tthis.stats = Stats();\n\t\t// Create right panel GUI\n\t\tthis.createParamsGUI(scope);\n\n\t\t// Initialization\n\t\tthis.inputManager = new InputManager(this, this.renderer.domElement);\n\t\tthis.cameraOperator = new CameraOperator(this, this.camera, this.params.Mouse_Sensitivity);\n\t\tthis.sky = new Sky(this);\n\t\t\n\t\t// Load scene if path is supplied\n\t\tif (worldScenePath !== undefined)\n\t\t{\n\t\t\tlet loadingManager = new LoadingManager(this);\n\t\t\tloadingManager.onFinishedCallback = () =>\n\t\t\t{\n\t\t\t\tthis.update(1, 1);\n\t\t\t\tthis.setTimeScale(1);\n\t\n\t\t\t\tSwal.fire({\n\t\t\t\t\ttitle: 'Sketchbook에 오신 것을 환영합니다!',\n\t\t\t\t\ttext: '자유롭게 세계를 탐험하고 차량에 탑승해 보세요. 오른쪽 패널에서 다양한 시나리오를 시작할 수 있습니다.',\n\t\t\t\t\tfooter: '<a href=\"https://github.com/swift502/Sketchbook\" target=\"_blank\">원본 GitHub</a><a href=\"https://discord.gg/fGuEqCe\" target=\"_blank\">Discord 커뮤니티</a>',\n\t\t\t\t\tconfirmButtonText: '시작하기',\n\t\t\t\t\tbuttonsStyling: false,\n\t\t\t\t\tonClose: () => {\n\t\t\t\t\t\tUIManager.setUserInterfaceVisible(true);\n\t\t\t\t\t}\n\t\t\t\t});\n\t\t\t};\n\t\t\tloadingManager.loadGLTF(worldScenePath, (gltf) =>\n\t\t\t\t{\n\t\t\t\t\tthis.loadScene(loadingManager, gltf);\n\t\t\t\t}\n\t\t\t);\n\t\t}\n\t\telse\n\t\t{\n\t\t\tUIManager.setUserInterfaceVisible(true);\n\t\t\tUIManager.setLoadingScreenVisible(false);\n\t\t\tSwal.fire({\n\t\t\t\ticon: 'success',\n\t\t\t\ttitle: '새로운 세계에 오신 것을 환영합니다!',\n\t\t\t\ttext: '빈 Sketchbook 세계를 준비했습니다. 푸른 하늘을 즐겨 보세요.',\n\t\t\t\tbuttonsStyling: false\n\t\t\t});\n\t\t}\n\n\t\tthis.render(this);\n\t}\n\n\t// Update\n\t// Handles all logic updates.\n\tpublic update(timeStep: number, unscaledTimeStep: number): void\n\t{\n\t\tthis.updatePhysics(timeStep);\n\n\t\t// Update registred objects\n\t\tthis.updatables.forEach((entity) => {\n\t\t\tentity.update(timeStep, unscaledTimeStep);\n\t\t});\n\n\t\t// Lerp time scale\n\t\tthis.params.Time_Scale = THREE.MathUtils.lerp(this.params.Time_Scale, this.timeScaleTarget, 0.2);\n\n\t\t// Physics debug\n\t\tif (this.params.Debug_Physics) this.cannonDebugRenderer.update();\n\t}\n\n\tpublic updatePhysics(timeStep: number): void\n\t{\n\t\t// Step the physics world\n\t\tthis.physicsWorld.step(this.physicsFrameTime, timeStep);\n\n\t\tthis.characters.forEach((char) => {\n\t\t\tif (this.isOutOfBounds(char.characterCapsule.body.position))\n\t\t\t{\n\t\t\t\tthis.outOfBoundsRespawn(char.characterCapsule.body);\n\t\t\t}\n\t\t});\n\n\t\tthis.vehicles.forEach((vehicle) => {\n\t\t\tif (this.isOutOfBounds(vehicle.rayCastVehicle.chassisBody.position))\n\t\t\t{\n\t\t\t\tlet worldPos = new THREE.Vector3();\n\t\t\t\tvehicle.spawnPoint.getWorldPosition(worldPos);\n\t\t\t\tworldPos.y += 1;\n\t\t\t\tthis.outOfBoundsRespawn(vehicle.rayCastVehicle.chassisBody, Utils.cannonVector(worldPos));\n\t\t\t}\n\t\t});\n\t}\n\n\tpublic isOutOfBounds(position: CANNON.Vec3): boolean\n\t{\n\t\tlet inside = position.x > -211.882 && position.x < 211.882 &&\n\t\t\t\t\tposition.z > -169.098 && position.z < 153.232 &&\n\t\t\t\t\tposition.y > 0.107;\n\t\tlet belowSeaLevel = position.y < 14.989;\n\n\t\treturn !inside && belowSeaLevel;\n\t}\n\n\tpublic outOfBoundsRespawn(body: CANNON.Body, position?: CANNON.Vec3): void\n\t{\n\t\tlet newPos = position || new CANNON.Vec3(0, 16, 0);\n\t\tlet newQuat = new CANNON.Quaternion(0, 0, 0, 1);\n\n\t\tbody.position.copy(newPos);\n\t\tbody.interpolatedPosition.copy(newPos);\n\t\tbody.quaternion.copy(newQuat);\n\t\tbody.interpolatedQuaternion.copy(newQuat);\n\t\tbody.velocity.setZero();\n\t\tbody.angularVelocity.setZero();\n\t}\n\n\t/**\n\t * Rendering loop.\n\t * Implements fps limiter and frame-skipping\n\t * Calls world's \"update\" function before rendering.\n\t * @param {World} world \n\t */\n\tpublic render(world: World): void\n\t{\n\t\tthis.requestDelta = this.clock.getDelta();\n\n\t\trequestAnimationFrame(() =>\n\t\t{\n\t\t\tworld.render(world);\n\t\t});\n\n\t\t// Getting timeStep\n\t\tlet unscaledTimeStep = (this.requestDelta + this.renderDelta + this.logicDelta) ;\n\t\tlet timeStep = unscaledTimeStep * this.params.Time_Scale;\n\t\ttimeStep = Math.min(timeStep, 1 / 30);    // min 30 fps\n\n\t\t// Logic\n\t\tworld.update(timeStep, unscaledTimeStep);\n\n\t\t// Measuring logic time\n\t\tthis.logicDelta = this.clock.getDelta();\n\n\t\t// Frame limiting\n\t\tlet interval = 1 / 60;\n\t\tthis.sinceLastFrame += this.requestDelta + this.renderDelta + this.logicDelta;\n\t\tthis.sinceLastFrame %= interval;\n\n\t\t// Stats end\n\t\tthis.stats.end();\n\t\tthis.stats.begin();\n\n\t\t// Actual rendering with a FXAA ON/OFF switch\n\t\tif (this.params.FXAA) this.composer.render();\n\t\telse this.renderer.render(this.graphicsWorld, this.camera);\n\n\t\t// Measuring render time\n\t\tthis.renderDelta = this.clock.getDelta();\n\t}\n\n\tpublic setTimeScale(value: number): void\n\t{\n\t\tthis.params.Time_Scale = value;\n\t\tthis.timeScaleTarget = value;\n\t}\n\n\tpublic add(worldEntity: IWorldEntity): void\n\t{\n\t\tworldEntity.addToWorld(this);\n\t\tthis.registerUpdatable(worldEntity);\n\t}\n\n\tpublic registerUpdatable(registree: IUpdatable): void\n\t{\n\t\tthis.updatables.push(registree);\n\t\tthis.updatables.sort((a, b) => (a.updateOrder > b.updateOrder) ? 1 : -1);\n\t}\n\n\tpublic remove(worldEntity: IWorldEntity): void\n\t{\n\t\tworldEntity.removeFromWorld(this);\n\t\tthis.unregisterUpdatable(worldEntity);\n\t}\n\n\tpublic unregisterUpdatable(registree: IUpdatable): void\n\t{\n\t\t_.pull(this.updatables, registree);\n\t}\n\n\tpublic loadScene(loadingManager: LoadingManager, gltf: any): void\n\t{\n\t\tgltf.scene.traverse((child) => {\n\t\t\tif (child.hasOwnProperty('userData'))\n\t\t\t{\n\t\t\t\tif (child.type === 'Mesh')\n\t\t\t\t{\n\t\t\t\t\tUtils.setupMeshProperties(child);\n\t\t\t\t\tthis.sky.csm.setupMaterial(child.material);\n\n\t\t\t\t\tif (child.material.name === 'ocean')\n\t\t\t\t\t{\n\t\t\t\t\t\tthis.registerUpdatable(new Ocean(child, this));\n\t\t\t\t\t}\n\t\t\t\t}\n\n\t\t\t\tif (child.userData.hasOwnProperty('data'))\n\t\t\t\t{\n\t\t\t\t\tif (child.userData.data === 'physics')\n\t\t\t\t\t{\n\t\t\t\t\t\tif (child.userData.hasOwnProperty('type')) \n\t\t\t\t\t\t{\n\t\t\t\t\t\t\t// Convex doesn't work! Stick to boxes!\n\t\t\t\t\t\t\tif (child.userData.type === 'box')\n\t\t\t\t\t\t\t{\n\t\t\t\t\t\t\t\tlet phys = new BoxCollider({size: new THREE.Vector3(child.scale.x, child.scale.y, child.scale.z)});\n\t\t\t\t\t\t\t\tphys.body.position.copy(Utils.cannonVector(child.position));\n\t\t\t\t\t\t\t\tphys.body.quaternion.copy(Utils.cannonQuat(child.quaternion));\n\t\t\t\t\t\t\t\tphys.body.computeAABB();\n\n\t\t\t\t\t\t\t\tphys.body.shapes.forEach((shape) => {\n\t\t\t\t\t\t\t\t\tshape.collisionFilterMask = ~CollisionGroups.TrimeshColliders;\n\t\t\t\t\t\t\t\t});\n\n\t\t\t\t\t\t\t\tthis.physicsWorld.addBody(phys.body);\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\telse if (child.userData.type === 'trimesh')\n\t\t\t\t\t\t\t{\n\t\t\t\t\t\t\t\tlet phys = new TrimeshCollider(child, {});\n\t\t\t\t\t\t\t\tthis.physicsWorld.addBody(phys.body);\n\t\t\t\t\t\t\t}\n\n\t\t\t\t\t\t\tchild.visible = false;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\n\t\t\t\t\tif (child.userData.data === 'path')\n\t\t\t\t\t{\n\t\t\t\t\t\tthis.paths.push(new Path(child));\n\t\t\t\t\t}\n\n\t\t\t\t\tif (child.userData.data === 'scenario')\n\t\t\t\t\t{\n\t\t\t\t\t\tthis.scenarios.push(new Scenario(child, this));\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t});\n\n\t\tthis.graphicsWorld.add(gltf.scene);\n\n\t\t// Launch default scenario\n\t\tlet defaultScenarioID: string;\n\t\tfor (const scenario of this.scenarios) {\n\t\t\tif (scenario.default) {\n\t\t\t\tdefaultScenarioID = scenario.id;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\tif (defaultScenarioID !== undefined) this.launchScenario(defaultScenarioID, loadingManager);\n\t}\n\t\n\tpublic launchScenario(scenarioID: string, loadingManager?: LoadingManager): void\n\t{\n\t\tthis.lastScenarioID = scenarioID;\n\n\t\tthis.clearEntities();\n\n\t\t// Launch default scenario\n\t\tif (!loadingManager) loadingManager = new LoadingManager(this);\n\t\tfor (const scenario of this.scenarios) {\n\t\t\tif (scenario.id === scenarioID || scenario.spawnAlways) {\n\t\t\t\tscenario.launch(loadingManager, this);\n\t\t\t}\n\t\t}\n\t}\n\n\tpublic restartScenario(): void\n\t{\n\t\tif (this.lastScenarioID !== undefined)\n\t\t{\n\t\t\tdocument.exitPointerLock();\n\t\t\tthis.launchScenario(this.lastScenarioID);\n\t\t}\n\t\telse\n\t\t{\n\t\t\tconsole.warn('Can\\'t restart scenario. Last scenarioID is undefined.');\n\t\t}\n\t}\n\n\tpublic clearEntities(): void\n\t{\n\t\tfor (let i = 0; i < this.characters.length; i++) {\n\t\t\tthis.remove(this.characters[i]);\n\t\t\ti--;\n\t\t}\n\n\t\tfor (let i = 0; i < this.vehicles.length; i++) {\n\t\t\tthis.remove(this.vehicles[i]);\n\t\t\ti--;\n\t\t}\n\t}\n\n\tpublic scrollTheTimeScale(scrollAmount: number): void\n\t{\n\t\t// Changing time scale with scroll wheel\n\t\tconst timeScaleBottomLimit = 0.003;\n\t\tconst timeScaleChangeSpeed = 1.3;\n\t\n\t\tif (scrollAmount > 0)\n\t\t{\n\t\t\tthis.timeScaleTarget /= timeScaleChangeSpeed;\n\t\t\tif (this.timeScaleTarget < timeScaleBottomLimit) this.timeScaleTarget = 0;\n\t\t}\n\t\telse\n\t\t{\n\t\t\tthis.timeScaleTarget *= timeScaleChangeSpeed;\n\t\t\tif (this.timeScaleTarget < timeScaleBottomLimit) this.timeScaleTarget = timeScaleBottomLimit;\n\t\t\tthis.timeScaleTarget = Math.min(this.timeScaleTarget, 1);\n\t\t}\n\t}\n\n\tpublic updateControls(controls: any): void\n\t{\n\t\tlet html = '';\n\t\thtml += '<h2 class=\"controls-title\">조작 방법</h2>';\n\n\t\tcontrols.forEach((row) =>\n\t\t{\n\t\t\thtml += '<div class=\"ctrl-row\">';\n\t\t\trow.keys.forEach((key) => {\n\t\t\t\tif (key === '+' || key === 'and' || key === 'or' || key === '&') html += '&nbsp;' + key + '&nbsp;';\n\t\t\t\telse html += '<span class=\"ctrl-key\">' + key + '</span>';\n\t\t\t});\n\n\t\t\thtml += '<span class=\"ctrl-desc\">' + row.desc + '</span></div>';\n\t\t});\n\n\t\tdocument.getElementById('controls').innerHTML = html;\n\t}\n\n\tprivate generateHTML(): void\n\t{\n\t\t// Fonts\n\t\t$('head').append('<link href=\"https://fonts.googleapis.com/css2?family=Noto+Sans+KR:wght@400;500;700&display=swap\" rel=\"stylesheet\">');\n\t\t$('head').append('<link href=\"https://fonts.googleapis.com/css2?family=Alfa+Slab+One&display=swap\" rel=\"stylesheet\">');\n\t\t$('head').append('<link href=\"https://fonts.googleapis.com/css2?family=Solway:wght@400;500;700&display=swap\" rel=\"stylesheet\">');\n\t\t$('head').append('<link href=\"https://fonts.googleapis.com/css2?family=Cutive+Mono&display=swap\" rel=\"stylesheet\">');\n\n\t\t// Loader\n\t\t$(`\t<div id=\"loading-screen\">\n\t\t\t\t<div id=\"loading-screen-background\"></div>\n\t\t\t\t<h1 id=\"main-title\" class=\"sb-font\">Sketchbook 0.4</h1>\n\t\t\t\t<div class=\"cubeWrap\">\n\t\t\t\t\t<div class=\"cube\">\n\t\t\t\t\t\t<div class=\"faces1\"></div>\n\t\t\t\t\t\t<div class=\"faces2\"></div>     \n\t\t\t\t\t</div> \n\t\t\t\t</div> \n\t\t\t\t<div id=\"loading-text\">불러오는 중...</div>\n\t\t\t</div>\n\t\t`).appendTo('body');\n\n\t\t// UI\n\t\t$(`\t<div id=\"ui-container\" style=\"display: none;\">\n\t\t\t\t<div class=\"github-corner\">\n\t\t\t\t\t<a href=\"https://github.com/swift502/Sketchbook\" target=\"_blank\" title=\"Fork me on GitHub\">\n\t\t\t\t\t\t<svg viewbox=\"0 0 100 100\" fill=\"currentColor\">\n\t\t\t\t\t\t\t<title>GitHub에서 원본 보기</title>\n\t\t\t\t\t\t\t<path d=\"M0 0v100h100V0H0zm60 70.2h.2c1 2.7.3 4.7 0 5.2 1.4 1.4 2 3 2 5.2 0 7.4-4.4 9-8.7 9.5.7.7 1.3 2\n\t\t\t\t\t\t\t1.3 3.7V99c0 .5 1.4 1 1.4 1H44s1.2-.5 1.2-1v-3.8c-3.5 1.4-5.2-.8-5.2-.8-1.5-2-3-2-3-2-2-.5-.2-1-.2-1\n\t\t\t\t\t\t\t2-.7 3.5.8 3.5.8 2 1.7 4 1 5 .3.2-1.2.7-2 1.2-2.4-4.3-.4-8.8-2-8.8-9.4 0-2 .7-4 2-5.2-.2-.5-1-2.5.2-5\n\t\t\t\t\t\t\t0 0 1.5-.6 5.2 1.8 1.5-.4 3.2-.6 4.8-.6 1.6 0 3.3.2 4.8.7 2.8-2 4.4-2 5-2z\"></path>\n\t\t\t\t\t\t</svg>\n\t\t\t\t\t</a>\n\t\t\t\t</div>\n\t\t\t\t<div class=\"left-panel\">\n\t\t\t\t\t<div id=\"controls\" class=\"panel-segment flex-bottom\"></div>\n\t\t\t\t</div>\n\t\t\t</div>\n\t\t`).appendTo('body');\n\n\t\t// Canvas\n\t\tdocument.body.appendChild(this.renderer.domElement);\n\t\tthis.renderer.domElement.id = 'canvas';\n\t}\n\n\tprivate createParamsGUI(scope: World): void\n\t{\n\t\tthis.params = {\n\t\t\tPointer_Lock: true,\n\t\t\tMouse_Sensitivity: 0.3,\n\t\t\tTime_Scale: 1,\n\t\t\tShadows: true,\n\t\t\tFXAA: true,\n\t\t\tDebug_Physics: false,\n\t\t\tDebug_FPS: false,\n\t\t\tSun_Elevation: 50,\n\t\t\tSun_Rotation: 145,\n\t\t};\n\n\t\tconst gui = new GUI.GUI();\n\n\t\t// Scenario\n\t\tthis.scenarioGUIFolder = gui.addFolder('시나리오');\n\t\tthis.scenarioGUIFolder.open();\n\n\t\t// World\n\t\tlet worldFolder = gui.addFolder('세계');\n\t\tworldFolder.add(this.params, 'Time_Scale', 0, 1).name('시간 흐름').listen()\n\t\t\t.onChange((value) =>\n\t\t\t{\n\t\t\t\tscope.timeScaleTarget = value;\n\t\t\t});\n\t\tworldFolder.add(this.params, 'Sun_Elevation', 0, 180).name('태양 높이').listen()\n\t\t\t.onChange((value) =>\n\t\t\t{\n\t\t\t\tscope.sky.phi = value;\n\t\t\t});\n\t\tworldFolder.add(this.params, 'Sun_Rotation', 0, 360).name('태양 방향').listen()\n\t\t\t.onChange((value) =>\n\t\t\t{\n\t\t\t\tscope.sky.theta = value;\n\t\t\t});\n\n\t\t// Input\n\t\tlet settingsFolder = gui.addFolder('설정');\n\t\tsettingsFolder.add(this.params, 'FXAA').name('계단 현상 완화');\n\t\tsettingsFolder.add(this.params, 'Shadows').name('그림자')\n\t\t\t.onChange((enabled) =>\n\t\t\t{\n\t\t\t\tif (enabled)\n\t\t\t\t{\n\t\t\t\t\tthis.sky.csm.lights.forEach((light) => {\n\t\t\t\t\t\tlight.castShadow = true;\n\t\t\t\t\t});\n\t\t\t\t}\n\t\t\t\telse\n\t\t\t\t{\n\t\t\t\t\tthis.sky.csm.lights.forEach((light) => {\n\t\t\t\t\t\tlight.castShadow = false;\n\t\t\t\t\t});\n\t\t\t\t}\n\t\t\t});\n\t\tsettingsFolder.add(this.params, 'Pointer_Lock').name('마우스 시점 고정')\n\t\t\t.onChange((enabled) =>\n\t\t\t{\n\t\t\t\tscope.inputManager.setPointerLock(enabled);\n\t\t\t});\n\t\tsettingsFolder.add(this.params, 'Mouse_Sensitivity', 0, 1).name('마우스 감도')\n\t\t\t.onChange((value) =>\n\t\t\t{\n\t\t\t\tscope.cameraOperator.setSensitivity(value, value * 0.8);\n\t\t\t});\n\t\tsettingsFolder.add(this.params, 'Debug_Physics').name('물리 디버그')\n\t\t\t.onChange((enabled) =>\n\t\t\t{\n\t\t\t\tif (enabled)\n\t\t\t\t{\n\t\t\t\t\tthis.cannonDebugRenderer = new CannonDebugRenderer( this.graphicsWorld, this.physicsWorld );\n\t\t\t\t}\n\t\t\t\telse\n\t\t\t\t{\n\t\t\t\t\tthis.cannonDebugRenderer.clearMeshes();\n\t\t\t\t\tthis.cannonDebugRenderer = undefined;\n\t\t\t\t}\n\n\t\t\t\tscope.characters.forEach((char) =>\n\t\t\t\t{\n\t\t\t\t\tchar.raycastBox.visible = enabled;\n\t\t\t\t});\n\t\t\t});\n\t\tsettingsFolder.add(this.params, 'Debug_FPS').name('FPS 표시')\n\t\t\t.onChange((enabled) =>\n\t\t\t{\n\t\t\t\tUIManager.setFPSVisible(enabled);\n\t\t\t});\n\n\t\tgui.open();\n\t}\n}", "README.en.md": "<p align=\"center\">\n\t<a href=\"https://jblaha.art/sketchbook/latest\"><img src=\"./src/img/thumbnail.png\"></a>\n\t<br>\n\t<a href=\"https://jblaha.art/sketchbook/latest\">Live demo</a>\n\t<br>\n</p>\n\n# Final update (20. Feb 2023)\n\nAs I have no more interest in developing this project, it comes to a conclusion. In order to remain honest about the true state of the project, I am archiving this repository.\n\n- If you wish to modify Sketchbook feel free to fork it.\n- To see if someone is currently maintaining a fork, check out the [Network Graph](https://github.com/swift502/Sketchbook/network).\n\n# 📒 Sketchbook\n\nSimple web based game engine built on [three.js](https://github.com/mrdoob/three.js) and [cannon.js](https://github.com/schteppe/cannon.js) focused on third-person character controls and related gameplay mechanics.\n\nMostly a playground for exploring how conventional third person gameplay mechanics found in modern games work and recreating them in a general way.\n\n## Features\n\n* World\n\t* Three.js scene\n\t* Cannon.js physics\n\t* Variable timescale\n\t* Frame skipping\n\t* FXAA anti-aliasing\n* Characters\n\t* Third-person camera\n\t* Raycast character controller with capsule collisions\n\t* General state system\n\t* Character AI\n* Vehicles\n\t* Cars\n\t* Airplanes\n\t* Helicopters\n\nAll planned features can be found in the [GitHub Projects](https://github.com/swift502/Sketchbook/projects).\n\n## Usage\n\nYou can define your own scenes in Blender, and then read them with Sketchbook. Sketchbook needs to run on a local server such as [http-server](https://www.npmjs.com/package/http-server) or [webpack-dev-server](https://github.com/webpack/webpack-dev-server) to be able to load external assets.\n\n<!-- #### Script tag -->\n\n1. Import:\n\n```html\n<script src=\"sketchbook.min.js\"></script>\n```\n\n2. Load a glb scene defined in Blender:\n\n```javascript\nconst world = new Sketchbook.World('scene.glb');\n```\n\n<!--\n\n#### NPM\n\n1. Install:\n\n```\nnpm i sketchbook\n```\n\n2. Import:\n\n```javascript\nimport { World } from 'sketchbook';\n```\n\n3. Load a glb scene defined in Blender:\n\n```javascript\nconst world = new World('scene.glb');\n```\n\n-->\n\n## Contributing\n\n1. Get the LTS version of [Node.js](https://nodejs.org/en/) 16\n2. [Fork this repository](https://help.github.com/en/github/getting-started-with-github/fork-a-repo)\n3. Run `npm install`\n4. Run `npm run dev`\n5. Make changes and test them out at http://localhost:8080\n6. Commit and [make a pull request](https://help.github.com/en/github/collaborating-with-issues-and-pull-requests/creating-a-pull-request-from-a-fork)!\n\n## Credits\n\nBig thank you to each of the following github users for contributing to Sketchbook:\n\n- [aleqsunder](https://github.com/aleqsunder)\n- [barhatsor](https://github.com/barhatsor)\n- [danshuri](https://github.com/danshuri)\n"};
for(const [path,data] of Object.entries(files)){if(path === 'README.md' && fs.existsSync(path)) continue;fs.mkdirSync(path.split('/').slice(0,-1).join('/')||'.',{recursive:true});fs.writeFileSync(path,data);}
